#[allow(clippy::too_many_arguments)]
async fn commit_iceberg_mv_target_files_with_ref(
    table: &iceberg::table::Table,
    catalog: &Arc<dyn Catalog>,
    entry: &crate::connector::iceberg::catalog::IcebergCatalogEntry,
    ident: &TableIdent,
    op_kind: CommitOpKind,
    data_files: Vec<DataFile>,
    target_ref: &str,
    snapshot_properties: BTreeMap<String, String>,
) -> Result<CommitOutcome, CommitServiceError> {
    let metadata = table.metadata();
    let staging_dir = format!(
        "{}/data/_staging/{}",
        metadata.location(),
        uuid::Uuid::new_v4()
    );
    let collector = Arc::new(
        IcebergCommitCollector::new(
            op_kind,
            ident.clone(),
            metadata
                .refs()
                .get(target_ref)
                .map(|r| r.snapshot_id)
                .or_else(|| {
                    if target_ref == "main" {
                        metadata.current_snapshot().map(|s| s.snapshot_id())
                    } else {
                        None
                    }
                }),
            metadata.last_sequence_number(),
            metadata.current_schema().clone(),
            metadata.default_partition_spec().clone(),
            staging_dir,
            crate::common::types::UniqueId { hi: 0, lo: 0 },
        )
        .with_table_metadata(metadata.clone()),
    );
    inject_iceberg_mv_data_file_reports(&collector, metadata, data_files)
        .map_err(CommitServiceError::invalid_input)?;

    let abort_cleanup = crate::engine::iceberg_writer::build_abort_cleanup_for_catalog_entry(entry)
        .map_err(CommitServiceError::invalid_input)?;

    let outcome = match run_iceberg_commit(RunInput {
        collector: collector.clone(),
        catalog: catalog.clone(),
        table: table.clone(),
        fs: abort_cleanup.fs,
        file_io: table.file_io().clone(),
        cleanup_path_mapper: abort_cleanup.path_mapper,
        cow_update_rewrite: None,
        target_ref: target_ref.to_string(),
        snapshot_properties,
    })
    .await
    {
        Ok(outcome) => outcome,
        Err(err) => {
            recover_mv_branch_commit_outcome(catalog, ident, &collector, target_ref, err).await?
        }
    };
    finalize_mv_branch_commit_outcome(catalog, ident, &collector, target_ref, outcome).await
}

/// IVM-A1 commit entrypoint: run the iceberg commit against a collector that
/// the merge sink already populated with `WrittenFile`s and
/// `PositionDeleteGroup`s. Mirrors the post-injection portion of
/// [`commit_iceberg_mv_apply_with_ref`] but skips collector construction so
/// the caller can share the collector with the sink.
///
/// The collector's `op_kind` must be set by the caller before any inject
/// calls — typically `CommitOpKind::RowDeltaDvFromFiles` when the change batch
/// has any DELETE-side rows, `CommitOpKind::FastAppend` otherwise.
#[allow(clippy::too_many_arguments)]
#[allow(dead_code)]
pub(crate) async fn commit_iceberg_mv_with_populated_collector(
    table: &iceberg::table::Table,
    catalog: &Arc<dyn Catalog>,
    entry: &crate::connector::iceberg::catalog::IcebergCatalogEntry,
    ident: &TableIdent,
    collector: Arc<IcebergCommitCollector>,
    target_ref: &str,
    snapshot_properties: BTreeMap<String, String>,
) -> Result<CommitOutcome, CommitServiceError> {
    let abort_cleanup = crate::engine::iceberg_writer::build_abort_cleanup_for_catalog_entry(entry)
        .map_err(CommitServiceError::invalid_input)?;
    let outcome = match run_iceberg_commit(RunInput {
        collector: collector.clone(),
        catalog: catalog.clone(),
        table: table.clone(),
        fs: abort_cleanup.fs,
        file_io: table.file_io().clone(),
        cleanup_path_mapper: abort_cleanup.path_mapper,
        cow_update_rewrite: None,
        target_ref: target_ref.to_string(),
        snapshot_properties,
    })
    .await
    {
        Ok(outcome) => outcome,
        Err(err) => {
            recover_mv_branch_commit_outcome(catalog, ident, &collector, target_ref, err).await?
        }
    };
    finalize_mv_branch_commit_outcome(catalog, ident, &collector, target_ref, outcome).await
}

#[allow(clippy::too_many_arguments)]
async fn commit_iceberg_mv_apply_with_ref(
    table: &iceberg::table::Table,
    catalog: &Arc<dyn Catalog>,
    entry: &crate::connector::iceberg::catalog::IcebergCatalogEntry,
    ident: &TableIdent,
    data_files: Vec<DataFile>,
    delete_groups: Vec<PositionDeleteGroup>,
    target_ref: &str,
    snapshot_properties: BTreeMap<String, String>,
) -> Result<CommitOutcome, CommitServiceError> {
    if delete_groups.is_empty() {
        return commit_iceberg_mv_target_files_with_ref(
            table,
            catalog,
            entry,
            ident,
            CommitOpKind::FastAppend,
            data_files,
            target_ref,
            snapshot_properties,
        )
        .await;
    }

    let metadata = table.metadata();
    let staging_dir = format!(
        "{}/data/_staging/{}",
        metadata.location(),
        uuid::Uuid::new_v4()
    );
    let collector = Arc::new(
        IcebergCommitCollector::new(
            CommitOpKind::RowDeltaDv,
            ident.clone(),
            metadata
                .refs()
                .get(target_ref)
                .map(|r| r.snapshot_id)
                .or_else(|| {
                    if target_ref == "main" {
                        metadata.current_snapshot().map(|s| s.snapshot_id())
                    } else {
                        None
                    }
                }),
            metadata.last_sequence_number(),
            metadata.current_schema().clone(),
            metadata.default_partition_spec().clone(),
            staging_dir,
            crate::common::types::UniqueId { hi: 0, lo: 0 },
        )
        .with_table_metadata(metadata.clone()),
    );
    inject_iceberg_mv_data_file_reports(&collector, metadata, data_files)
        .map_err(CommitServiceError::invalid_input)?;
    for group in delete_groups {
        collector.inject_delete_group(group);
    }

    let abort_cleanup = crate::engine::iceberg_writer::build_abort_cleanup_for_catalog_entry(entry)
        .map_err(CommitServiceError::invalid_input)?;
    let outcome = match run_iceberg_commit(RunInput {
        collector: collector.clone(),
        catalog: catalog.clone(),
        table: table.clone(),
        fs: abort_cleanup.fs,
        file_io: table.file_io().clone(),
        cleanup_path_mapper: abort_cleanup.path_mapper,
        cow_update_rewrite: None,
        target_ref: target_ref.to_string(),
        snapshot_properties,
    })
    .await
    {
        Ok(outcome) => outcome,
        Err(err) => {
            recover_mv_branch_commit_outcome(catalog, ident, &collector, target_ref, err).await?
        }
    };
    finalize_mv_branch_commit_outcome(catalog, ident, &collector, target_ref, outcome).await
}

fn inject_iceberg_mv_data_file_reports(
    collector: &IcebergCommitCollector,
    metadata: &iceberg::spec::TableMetadata,
    data_files: Vec<DataFile>,
) -> Result<(), String> {
    let default_spec_id = metadata.default_partition_spec_id();
    let written_files = data_files
        .into_iter()
        .map(|df| crate::engine::iceberg_writer::data_file_to_written_file(&df, default_spec_id))
        .collect::<Result<Vec<_>, _>>()?;
    collector.inject_written_files(written_files);
    Ok(())
}

fn derive_refresh_contract_for_strategy_dispatch(
    state: &Arc<StandaloneState>,
    current_catalog: Option<&str>,
    current_database: &str,
    mv_definition: &StoredMvDefinition,
    base_refs: &[TableIdentity],
    target: &IcebergMvTarget,
    target_table: &iceberg::table::Table,
    connector_context: &novarocks_spi::connector::ConnectorRequestContext,
) -> Result<
    (
        sqlparser::ast::Query,
        crate::mv::refresh::contract::ImvRefreshContract,
    ),
    String,
> {
    let select_query = parse_mv_select_query(&mv_definition.select_sql)?;
    match derive_refresh_contract_from_query(
        state,
        current_catalog,
        current_database,
        &select_query,
        connector_context,
    ) {
        Ok(contract) => Ok((select_query, contract)),
        Err(original_err) => {
            let Some(rewritten_sql) = try_rewrite_select_sql_for_strategy_dispatch_rebind(
                state,
                mv_definition,
                base_refs,
                target,
                target_table,
            )?
            else {
                return Err(original_err);
            };
            let rewritten_query = parse_mv_select_query(&rewritten_sql)?;
            let contract = derive_refresh_contract_from_query(
                state,
                current_catalog,
                current_database,
                &rewritten_query,
                connector_context,
            )
            .map_err(|rebound_err| {
                format!(
                    "{original_err}; after schema-contract rebind for refresh strategy dispatch: {rebound_err}"
                )
            })?;
            Ok((rewritten_query, contract))
        }
    }
}

fn derive_refresh_contract_from_query(
    state: &Arc<StandaloneState>,
    current_catalog: Option<&str>,
    current_database: &str,
    select_query: &sqlparser::ast::Query,
    connector_context: &novarocks_spi::connector::ConnectorRequestContext,
) -> Result<crate::mv::refresh::contract::ImvRefreshContract, String> {
    let analysis = analyze_mv_select_with_connector_context(
        state,
        current_catalog,
        current_database,
        select_query,
        connector_context,
    )?;
    derive_imv_refresh_contract(&analysis)
}

fn try_rewrite_select_sql_for_strategy_dispatch_rebind(
    state: &Arc<StandaloneState>,
    mv_definition: &StoredMvDefinition,
    base_refs: &[TableIdentity],
    target: &IcebergMvTarget,
    target_table: &iceberg::table::Table,
) -> Result<Option<String>, String> {
    let Some(schema_contract) = mv_definition.schema_contract.as_ref() else {
        return Ok(None);
    };
    if schema_contract.join.is_some() {
        let [left_ref, right_ref] = base_refs else {
            return Ok(None);
        };
        let left_loaded = load_current_iceberg_base_table(state, left_ref)?;
        let right_loaded = load_current_iceberg_base_table(state, right_ref)?;
        let join_bases = [
            (left_ref, &left_loaded.table),
            (right_ref, &right_loaded.table),
        ];
        return match validate_current_join_schema_contract(
            schema_contract,
            &join_bases,
            target_table,
        )
        .map_err(|error| error.to_string())?
        {
            JoinContractDecision::CompatibleSafe => Ok(None),
            JoinContractDecision::CompatibleSafeWithRebind { rebound_columns } => {
                rewrite_select_sql_for_rebind(&mv_definition.select_sql, &rebound_columns).map(Some)
            }
        };
    }
    if !schema_contract.bases.is_empty() {
        if schema_contract.aggregate.is_some()
            && schema_contract.join.is_none()
            && schema_contract.branch.is_none()
        {
            for base_ref in base_refs {
                let loaded = load_current_iceberg_base_table(state, base_ref)?;
                validate_aggregate_schema_contract_for_base(
                    schema_contract,
                    base_ref,
                    &loaded.table,
                    target_table,
                )?;
            }
        }
        return Ok(None);
    }
    let [base_ref] = base_refs else {
        return Ok(None);
    };
    let loaded = load_current_iceberg_base_table(state, base_ref)?;
    match validate_current_schema_contract(schema_contract, &loaded.table, target_table) {
        ContractDecision::Incompatible(err) => Err(format!("{err}")),
        ContractDecision::CompatibleSafe => Ok(None),
        ContractDecision::CompatibleSafeWithRebind { rebound_columns } => {
            tracing::info!(
                target = ?target,
                rebound = ?rebound_columns,
                "iceberg MV refresh strategy dispatch: base columns rebound by field id; deriving contract from rewritten select_sql",
            );
            rewrite_select_sql_for_rebind(&mv_definition.select_sql, &rebound_columns).map(Some)
        }
    }
}

pub(crate) fn parse_mv_select_query(sql: &str) -> Result<sqlparser::ast::Query, String> {
    let normalized = crate::sql::parser::dialect::normalize_for_raw_parse(sql)
        .map_err(|e| format!("stored MV SELECT normalize error: {e}"))?;
    let statement = crate::sql::parser::parse_normalized_sql_raw(&normalized)
        .map_err(|err| format!("sql parser error: {err}"))?;
    let sqlparser::ast::Statement::Query(query) = statement else {
        return Err("stored MV SQL must be a SELECT query".to_string());
    };
    Ok(*query)
}

fn expected_main_snapshot_id_from_table(table: &iceberg::table::Table) -> Option<i64> {
    table.metadata().current_snapshot().map(|s| s.snapshot_id())
}

fn ensure_schema_contract_compatible_for_refresh(
    schema_contract: &mv_schema::MvSchemaContract,
    base_table: &iceberg::table::Table,
    target_table: &iceberg::table::Table,
) -> Result<(), String> {
    match validate_current_schema_contract(schema_contract, base_table, target_table) {
        ContractDecision::Incompatible(err) => Err(format!("{err}")),
        ContractDecision::CompatibleSafe | ContractDecision::CompatibleSafeWithRebind { .. } => {
            Ok(())
        }
    }
}

fn validate_repartition_schema_contract(
    state: &Arc<StandaloneState>,
    schema_contract: &mv_schema::MvSchemaContract,
    base_refs: &[TableIdentity],
    target_table: &iceberg::table::Table,
) -> Result<(), String> {
    if schema_contract.join.is_some() {
        let [left_ref, right_ref] = base_refs else {
            return Err(format!(
                "Iceberg join MV repartition schema contract requires exactly two base tables, got {}",
                base_refs.len()
            ));
        };
        let left_loaded = load_current_iceberg_base_table(state, left_ref)?;
        let right_loaded = load_current_iceberg_base_table(state, right_ref)?;
        match validate_current_join_schema_contract(
            schema_contract,
            &[
                (left_ref, &left_loaded.table),
                (right_ref, &right_loaded.table),
            ],
            target_table,
        )
        .map_err(|error| error.to_string())?
        {
            JoinContractDecision::CompatibleSafe => {}
            JoinContractDecision::CompatibleSafeWithRebind { rebound_columns } => {
                if schema_contract.aggregate.is_some() {
                    return Err(format!(
                        "iceberg join aggregate MV repartition requires schema rebind for {rebound_columns:?}, which is not supported during repartition; recreate the MV"
                    ));
                }
            }
        }
        return Ok(());
    }

    if !schema_contract.bases.is_empty() {
        for base_ref in base_refs {
            let loaded = load_current_iceberg_base_table(state, base_ref)?;
            if schema_contract.aggregate.is_some() {
                validate_aggregate_repartition_schema_contract_for_base(
                    schema_contract,
                    base_ref,
                    &loaded.table,
                    target_table,
                )?;
            } else {
                validate_repartition_base_schema_contract(
                    schema_contract,
                    base_ref,
                    &loaded.table,
                    target_table,
                )?;
            }
        }
        return Ok(());
    }

    let [base_ref] = base_refs else {
        return Err(format!(
            "ALTER MATERIALIZED VIEW ... REPARTITION single-base schema contract requires exactly one base table, got {}",
            base_refs.len()
        ));
    };
    let loaded = load_current_iceberg_base_table(state, base_ref)?;
    if schema_contract.aggregate.is_some() {
        validate_aggregate_repartition_schema_contract_for_base(
            schema_contract,
            base_ref,
            &loaded.table,
            target_table,
        )
    } else {
        ensure_schema_contract_compatible_for_refresh(schema_contract, &loaded.table, target_table)
    }
}

fn validate_aggregate_repartition_schema_contract_for_base(
    schema_contract: &mv_schema::MvSchemaContract,
    base_ref: &TableIdentity,
    base_table: &iceberg::table::Table,
    target_table: &iceberg::table::Table,
) -> Result<(), String> {
    validate_aggregate_schema_contract_for_base(
        schema_contract,
        base_ref,
        base_table,
        target_table,
    )
    .map_err(|err| {
        if err.contains("requires schema rebind") {
            format!(
                "iceberg aggregate MV repartition requires schema rebind for base {}, which is not supported during repartition; recreate the MV",
                base_ref.fqn()
            )
        } else {
            err
        }
    })
}

fn validate_repartition_base_schema_contract(
    schema_contract: &mv_schema::MvSchemaContract,
    base_ref: &TableIdentity,
    base_table: &iceberg::table::Table,
    target_table: &iceberg::table::Table,
) -> Result<(), String> {
    let mut base_contract = schema_contract.clone();
    base_contract.base = schema_contract
        .bases
        .iter()
        .find(|base| base.table_fqn.eq_ignore_ascii_case(&base_ref.fqn()))
        .cloned()
        .ok_or_else(|| {
            format!(
                "Iceberg MV repartition schema contract missing base {}; recreate the MV",
                base_ref.fqn()
            )
        })?;
    match validate_current_schema_contract(&base_contract, base_table, target_table) {
        ContractDecision::Incompatible(err) => Err(format!("{err}")),
        ContractDecision::CompatibleSafe | ContractDecision::CompatibleSafeWithRebind { .. } => {
            Ok(())
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn refresh_iceberg_join_mv(
    state: &Arc<StandaloneState>,
    target: &IcebergMvTarget,
    target_entry: &crate::connector::iceberg::catalog::IcebergCatalogEntry,
    iceberg_catalog: &Arc<dyn iceberg::Catalog>,
    target_table: &iceberg::table::Table,
    current_catalog: Option<&str>,
    current_database: &str,
    mv_definition: &StoredMvDefinition,
    base_refs: &[TableIdentity],
    apply_key: ApplyKeyContract,
    execution: &IcebergValidatedRefreshExecution<'_>,
) -> Result<StatementResult, IcebergMvRefreshExecutionError> {
    if base_refs.len() != 2 {
        return Err("iceberg join MV refresh requires exactly two base tables"
            .to_string()
            .into());
    }
    if apply_key != ApplyKeyContract::join_projection_filter() {
        return Err(
            "iceberg join MV refresh contract did not match join projection/filter apply key"
                .to_string()
                .into(),
        );
    }
    let schema_contract = mv_definition.schema_contract.as_ref().ok_or_else(|| {
        format!(
            "iceberg MV target {}.{}.{} is missing A11 schema contract; rebuild or recreate the MV",
            target.catalog, target.namespace, target.table
        )
    })?;
    if schema_contract.contract_version != 2 {
        return Err(format!(
            "iceberg join MV {}.{}.{} requires schema contract version 2, got {}",
            target.catalog, target.namespace, target.table, schema_contract.contract_version
        )
        .into());
    }
    let (left_ref, right_ref) = join_base_refs_for_schema_contract(schema_contract, base_refs)?;
    let left_loaded_before_pin = load_current_iceberg_base_table(state, left_ref)?;
    let right_loaded_before_pin = load_current_iceberg_base_table(state, right_ref)?;
    let pre_pin_join_bases = [
        (left_ref, &left_loaded_before_pin.table),
        (right_ref, &right_loaded_before_pin.table),
    ];
    let _ =
        validate_current_join_schema_contract(schema_contract, &pre_pin_join_bases, target_table)
            .map_err(|error| error.to_string())?;

    match execution.decision() {
        ExecutableRefreshDecision::SkipEmpty => {
            tracing::info!(
                "iceberg join mv {}.{}.{}: both base tables have no snapshot; skipping refresh",
                target.catalog,
                target.namespace,
                target.table
            );
            return Ok(StatementResult::Ok);
        }
        ExecutableRefreshDecision::FirstRefresh
        | ExecutableRefreshDecision::MetadataOnly
        | ExecutableRefreshDecision::Incremental => {}
    }

    let pin = execution.pin()?;
    if pin.len() != 2 {
        return Err(format!(
            "iceberg join MV refresh expected two refresh pins, got {}",
            pin.len()
        )
        .into());
    }
    let left_loaded = load_current_iceberg_base_table(state, left_ref)?;
    let right_loaded = load_current_iceberg_base_table(state, right_ref)?;
    let decision = validate_current_join_schema_contract(
        schema_contract,
        &[
            (left_ref, &left_loaded.table),
            (right_ref, &right_loaded.table),
        ],
        target_table,
    )
    .map_err(|error| error.to_string())?;
    let effective_definition = apply_join_schema_contract_decision(decision, mv_definition)?;
    let mv_definition = &effective_definition;

    // Construct the refresh context once after join schema validation. The
    // validated execution owns the previously captured pin; SkipEmpty reaches
    // this branch without requiring one, preserving the early no-op behavior.
    let canonical_select_query = canonicalize_iceberg_mv_select_query(
        &parse_mv_select_query(&mv_definition.select_sql)?,
        current_catalog,
        current_database,
    );
    let ctx = build_validated_refresh_context(
        ValidatedRefreshShape::JoinProjection,
        state,
        target.clone(),
        current_catalog,
        current_database,
        Arc::new(mv_definition.clone()),
        Arc::new(canonical_select_query),
        Arc::from(base_refs.to_vec()),
        execution,
        Arc::new(target_entry.clone()),
        iceberg_catalog.clone(),
        target_table.clone(),
    )?;
    tracing::info!(
        summary = ?ctx.rewrite.summary(),
        "iceberg MV refresh context constructed"
    );

    dispatch_refresh_decision(
        execution.decision(),
        || Ok(StatementResult::Ok),
        || {
            let staging_branch = format!(
                "__nova_mv_refresh_{}_{}",
                mv_definition.mv_id,
                uuid::Uuid::new_v4().simple()
            );
            let refresh_id = begin_staged_iceberg_mv_refresh_intent(
                state,
                target,
                mv_definition.mv_id,
                ctx.rewrite.target_snapshot_id,
                pin.to_snapshot_map(),
                &staging_branch,
            )?;
            first_refresh_iceberg_join_mv(
                state,
                &ctx,
                &staging_branch,
                refresh_id,
                left_ref,
                right_ref,
            )
        },
        || {
            tracing::info!(
                "iceberg join mv {}.{}.{}: base snapshots unchanged; updating metadata only",
                target.catalog,
                target.namespace,
                target.table
            );
            Ok(
                finalize_iceberg_mv_metadata_only_refresh_with_partition_state(
                    state,
                    target,
                    mv_definition,
                    pin.to_snapshot_map(),
                    pin.to_table_uuid_map(),
                    IcebergMvPartitionStateFinalize::FromAffected(&ctx.affected_partitions),
                )?,
            )
        },
        || incremental_refresh_iceberg_join_mv(state, &ctx, &[left_ref.clone(), right_ref.clone()]),
    )
}

fn validate_join_aliases_base_refs(
    aliases: &crate::mv::aggregate_state::aggregate_sql_calls::JoinAliases,
    base_refs: &[TableIdentity],
) -> Result<(), String> {
    for name in [
        aliases.left_table.to_ascii_lowercase(),
        aliases.right_table.to_ascii_lowercase(),
    ] {
        if !base_refs
            .iter()
            .any(|base| base.fqn().eq_ignore_ascii_case(&name))
        {
            return Err(format!(
                "join MV references base {name} but analyzer resolved {base_refs:?}"
            ));
        }
    }
    Ok(())
}

/// Resolves the left/right `base_refs` for a join MV by matching
/// `JoinAliases.{left_table,right_table}` (the `ObjectName.to_string()` FQN form)
/// against `base.fqn()`.
fn join_base_refs_for_aliases<'a>(
    aliases: &crate::mv::aggregate_state::aggregate_sql_calls::JoinAliases,
    base_refs: &'a [TableIdentity],
) -> Result<(&'a TableIdentity, &'a TableIdentity), String> {
    let left_name = aliases.left_table.as_str();
    let right_name = aliases.right_table.as_str();
    let left = base_refs
        .iter()
        .find(|base| base.fqn().eq_ignore_ascii_case(left_name))
        .ok_or_else(|| format!("join MV left base {left_name} was not resolved"))?;
    let right = base_refs
        .iter()
        .find(|base| base.fqn().eq_ignore_ascii_case(right_name))
        .ok_or_else(|| format!("join MV right base {right_name} was not resolved"))?;
    Ok((left, right))
}

fn join_base_refs_for_schema_contract<'a>(
    schema_contract: &mv_schema::MvSchemaContract,
    base_refs: &'a [TableIdentity],
) -> Result<(&'a TableIdentity, &'a TableIdentity), String> {
    let join = schema_contract
        .join
        .as_ref()
        .ok_or_else(|| "join MV schema contract missing join lineage".to_string())?;
    let predicate = join
        .predicates
        .first()
        .ok_or_else(|| "join MV schema contract has no join predicates".to_string())?;
    let left_name = predicate.left.table_fqn.as_str();
    let right_name = predicate.right.table_fqn.as_str();
    if left_name.eq_ignore_ascii_case(right_name) {
        return Err(format!(
            "join MV schema contract has identical left/right bases: {left_name}"
        ));
    }
    let left = base_refs
        .iter()
        .find(|base| base.fqn().eq_ignore_ascii_case(left_name))
        .ok_or_else(|| format!("join MV left base {left_name} was not resolved"))?;
    let right = base_refs
        .iter()
        .find(|base| base.fqn().eq_ignore_ascii_case(right_name))
        .ok_or_else(|| format!("join MV right base {right_name} was not resolved"))?;
    Ok((left, right))
}

fn validate_refresh_pin_table_uuids(
    mv_definition: &StoredMvDefinition,
    pin: &RefreshSnapshotPin,
    base_refs: &[TableIdentity],
) -> Result<(), String> {
    validate_refresh_pin_table_uuids_for_operation(
        mv_definition,
        pin,
        base_refs,
        "incremental refresh is unsafe, rebuild or recreate the MV",
    )
}

fn validate_repartition_refresh_pin_table_uuids(
    mv_definition: &StoredMvDefinition,
    pin: &RefreshSnapshotPin,
    base_refs: &[TableIdentity],
) -> Result<(), String> {
    validate_refresh_pin_table_uuids_for_operation(
        mv_definition,
        pin,
        base_refs,
        "repartition is unsafe, recreate the MV",
    )
}

fn validate_refresh_pin_table_uuids_for_operation(
    mv_definition: &StoredMvDefinition,
    pin: &RefreshSnapshotPin,
    base_refs: &[TableIdentity],
    unsafe_message: &str,
) -> Result<(), String> {
    for base_ref in base_refs {
        let Some(previous_uuid) = mv_definition.last_refresh_table_uuids.get(&base_ref.fqn())
        else {
            continue;
        };
        let current_uuid = pin.uuid(base_ref).ok_or_else(|| {
            format!(
                "refresh pin missing uuid for base {} (this should not happen)",
                base_ref.fqn()
            )
        })?;
        if previous_uuid != current_uuid {
            return Err(format!(
                "iceberg MV base table identity changed for {}; {unsafe_message}",
                base_ref.fqn(),
            ));
        }
    }
    Ok(())
}

fn apply_join_schema_contract_decision(
    decision: JoinContractDecision,
    mv_definition: &StoredMvDefinition,
) -> Result<StoredMvDefinition, String> {
    match decision {
        JoinContractDecision::CompatibleSafe => Ok(mv_definition.clone()),
        JoinContractDecision::CompatibleSafeWithRebind { rebound_columns } => {
            let rewritten_sql =
                rewrite_select_sql_for_rebind(&mv_definition.select_sql, &rebound_columns)?;
            let mut definition = mv_definition.clone();
            definition.select_sql = rewritten_sql;
            Ok(definition)
        }
    }
}

fn iceberg_change_batch_has_row_deletes(
    batch: &crate::connector::iceberg::changes::IcebergChangeBatch,
) -> bool {
    !batch.deletes.is_empty()
        || !batch.equality_deletes.is_empty()
        || !batch.deleted_data_files.is_empty()
}

fn finalize_iceberg_mv_metadata_only_refresh(
    state: &Arc<StandaloneState>,
    target: &IcebergMvTarget,
    mv_definition: &StoredMvDefinition,
    snapshots: BTreeMap<String, i64>,
    table_uuids: BTreeMap<String, String>,
) -> Result<StatementResult, IcebergMvRefreshExecutionError> {
    finalize_iceberg_mv_metadata_only_refresh_with_partition_state(
        state,
        target,
        mv_definition,
        snapshots,
        table_uuids,
        IcebergMvPartitionStateFinalize::Clear,
    )
}

fn finalize_iceberg_mv_metadata_only_refresh_with_partition_state(
    state: &Arc<StandaloneState>,
    target: &IcebergMvTarget,
    mv_definition: &StoredMvDefinition,
    snapshots: BTreeMap<String, i64>,
    table_uuids: BTreeMap<String, String>,
    partition_state: IcebergMvPartitionStateFinalize<'_>,
) -> Result<StatementResult, IcebergMvRefreshExecutionError> {
    let target_snapshot_id = recorded_target_snapshot_id(target, mv_definition)
        .map_err(IcebergMvRefreshExecutionError::pre_commit)?;
    let refresh_id = begin_iceberg_mv_refresh_intent(state, mv_definition.mv_id, snapshots.clone())
        .map_err(IcebergMvRefreshExecutionError::pre_commit)?;
    finalize_iceberg_mv_refresh_with_partition_state(
        state,
        refresh_id,
        mv_definition.last_refresh_rows.unwrap_or(0),
        snapshots,
        table_uuids,
        target_snapshot_id,
        partition_state,
    )
    .map_err(iceberg_mv_post_publish_finalize_error)?;
    Ok(StatementResult::Ok)
}

#[allow(clippy::too_many_arguments)]
fn build_join_projection_repartition_context(
    state: &Arc<StandaloneState>,
    target: &IcebergMvTarget,
    target_entry: &crate::connector::iceberg::catalog::IcebergCatalogEntry,
    iceberg_catalog: &Arc<dyn iceberg::Catalog>,
    target_table: &iceberg::table::Table,
    schema_validation_target_table: &iceberg::table::Table,
    current_catalog: Option<&str>,
    current_database: &str,
    mv_definition: &StoredMvDefinition,
    base_refs: &[TableIdentity],
    pin: &RefreshSnapshotPin,
    aliases: &crate::mv::aggregate_state::aggregate_sql_calls::JoinAliases,
    connector_context: &novarocks_spi::connector::ConnectorRequestContext,
) -> Result<(IcebergMvRefreshContext, TableIdentity, TableIdentity), String> {
    if base_refs.len() != 2 {
        return Err("iceberg join MV repartition requires exactly two base tables".to_string());
    }
    if pin.len() != 2 {
        return Err(format!(
            "iceberg join MV repartition expected two refresh pins, got {}",
            pin.len()
        ));
    }
    validate_join_aliases_base_refs(aliases, base_refs)?;
    let schema_contract = mv_definition.schema_contract.as_ref().ok_or_else(|| {
        format!(
            "iceberg MV target {}.{}.{} is missing A11 schema contract; recreate the MV before repartitioning",
            target.catalog, target.namespace, target.table
        )
    })?;
    if schema_contract.contract_version != 2 {
        return Err(format!(
            "iceberg join MV {}.{}.{} requires schema contract version 2, got {}",
            target.catalog, target.namespace, target.table, schema_contract.contract_version
        ));
    }
    let (left_ref, right_ref) = join_base_refs_for_aliases(aliases, base_refs)?;
    let left_loaded = load_current_iceberg_base_table(state, left_ref)?;
    let right_loaded = load_current_iceberg_base_table(state, right_ref)?;
    let decision = validate_current_join_schema_contract(
        schema_contract,
        &[
            (left_ref, &left_loaded.table),
            (right_ref, &right_loaded.table),
        ],
        schema_validation_target_table,
    )
    .map_err(|error| error.to_string())?;
    let effective_definition = apply_join_schema_contract_decision(decision, mv_definition)?;
    let canonical_select_query = canonicalize_iceberg_mv_select_query(
        &parse_mv_select_query(&effective_definition.select_sql)?,
        current_catalog,
        current_database,
    );
    let mut ctx = {
        let iceberg_catalog_guard = state
            .iceberg_catalogs
            .read()
            .map_err(|e| format!("iceberg catalog registry read lock: {e}"))?;
        IcebergMvRefreshContext::new_with_pruning_limits(
            TableIdentity {
                catalog: target.catalog.clone(),
                namespace: target.namespace.clone(),
                table: target.table.clone(),
            },
            effective_definition.mv_id,
            current_catalog,
            current_database,
            Arc::new(effective_definition),
            Arc::new(canonical_select_query),
            Arc::from(base_refs.to_vec()),
            Arc::new(pin.clone()),
            &iceberg_catalog_guard,
            Arc::new(target_entry.clone()),
            iceberg_catalog.clone(),
            target_table.clone(),
            state.mv_refresh_pruning_limits,
        )?
    };
    ctx.connector_context = Some(connector_context.clone());
    Ok((ctx, left_ref.clone(), right_ref.clone()))
}

#[allow(clippy::too_many_arguments)]
fn repartition_iceberg_join_mv_overwrite(
    state: &Arc<StandaloneState>,
    ctx: &IcebergMvRefreshContext,
    staging_branch: &str,
    refresh_id: i64,
    left_ref: &TableIdentity,
    right_ref: &TableIdentity,
    partition_contract: &mv_schema::MvPartitionContract,
    repartition_restore: RepartitionDefaultSpecRestore,
) -> Result<StatementResult, IcebergMvRefreshExecutionError> {
    let application_target = IcebergMvTarget::from(&ctx.rewrite.target);
    let target = &application_target;
    let target_entry = ctx.target_bindings.runtime().target_entry();
    let iceberg_catalog = &ctx.iceberg_catalog;
    let expected_main_snapshot_id = ctx.rewrite.target_snapshot_id;
    let mv_definition = &*ctx.rewrite.mv_definition;
    let connector_context = refresh_connector_context(ctx)?;
    let ident = match iceberg_mv_table_ident(target) {
        Ok(ident) => ident,
        Err(err) => {
            return Err(abort_and_restore_iceberg_mv_repartition_default_spec(
                state,
                refresh_id,
                target_entry,
                target,
                repartition_restore.new_default_spec_id,
                repartition_restore.old_default_spec_id,
                err,
            )
            .into());
        }
    };
    let marker = match load_iceberg_mv_refresh_marker(state, refresh_id, mv_definition.mv_id) {
        Ok(marker) => marker.to_summary_properties(),
        Err(err) => {
            return Err(abort_and_restore_iceberg_mv_repartition_default_spec(
                state,
                refresh_id,
                target_entry,
                target,
                repartition_restore.new_default_spec_id,
                repartition_restore.old_default_spec_id,
                err,
            )
            .into());
        }
    };
    if let Err(err) = ensure_iceberg_mv_staging_branch(
        state,
        iceberg_catalog,
        target,
        staging_branch,
        expected_main_snapshot_id,
        connector_context,
    ) {
        return Err(abort_and_restore_iceberg_mv_repartition_default_spec(
            state,
            refresh_id,
            target_entry,
            target,
            repartition_restore.new_default_spec_id,
            repartition_restore.old_default_spec_id,
            err,
        )
        .into());
    }
    let target_table = match reload_iceberg_mv_target_table(target_entry, target) {
        Ok(table) => table,
        Err(err) => {
            return Err(
                handle_iceberg_mv_definite_pre_publish_error_with_repartition_restore(
                    state,
                    target,
                    target_entry,
                    staging_branch,
                    refresh_id,
                    err,
                    Some(repartition_restore),
                    connector_context,
                ),
            );
        }
    };
    let (plan, factory) = match plan_canonical_select_for_imv(state, ctx) {
        Ok(planned) => planned,
        Err(err) => {
            return Err(
                handle_iceberg_mv_definite_pre_publish_error_with_repartition_restore(
                    state,
                    target,
                    target_entry,
                    staging_branch,
                    refresh_id,
                    err.message,
                    Some(repartition_restore),
                    connector_context,
                ),
            );
        }
    };
    let target_backend = iceberg_mv_target_backend(target);
    let populated = execute_join_repartition_write(
        &target_table,
        &ident,
        staging_branch,
        &ctx.rewrite,
        left_ref,
        right_ref,
        crate::mv::refresh::join_first_refresh::JoinFirstRefreshLogicalInput { plan, factory },
        |logical| {
            let connectors_snapshot = state
                .connectors
                .read()
                .expect("standalone connector registry read lock")
                .clone();
            let planned_query = crate::engine::plan_logical_for_iceberg_change_stream_refresh(
                logical.plan,
                logical.factory,
                &connectors_snapshot,
            )?;
            execute_imv_change_stream_writer(
                state,
                &target_backend,
                &target_table,
                ImvRefreshPlannedChangeStream {
                    optimized_tree: planned_query.optimized_tree,
                    output_columns: planned_query.output_columns,
                    change_stream: logical.change_stream,
                    producer_branches: vec![ImvChangeStreamProducerBranch::FreshData],
                    mv_refresh_ctx: Some(ctx),
                },
                staging_branch,
            )
        },
    )
    .map_err(|err| {
        IcebergMvRefreshExecutionError::from(
            handle_iceberg_mv_definite_pre_publish_error_with_repartition_restore(
                state,
                target,
                target_entry,
                staging_branch,
                refresh_id,
                err.into_message(),
                Some(repartition_restore),
                connector_context,
            ),
        )
    })?;

    let total_rows = match populated.effect {
        crate::mv::refresh::change_stream_write::ChangeStreamWriteEffect::Empty => 0,
        crate::mv::refresh::change_stream_write::ChangeStreamWriteEffect::Changed {
            added_rows,
            ..
        } => added_rows,
    };
    let collector = populated.collector;
    let commit_outcome = match data_block_on(commit_iceberg_mv_with_populated_collector(
        &target_table,
        iceberg_catalog,
        target_entry,
        &ident,
        Arc::clone(&collector),
        staging_branch,
        marker,
    )) {
        Ok(Ok(outcome)) => outcome,
        Ok(Err(err)) => {
            return Err(
                handle_iceberg_mv_commit_service_error_with_repartition_restore(
                    state,
                    target,
                    target_entry,
                    staging_branch,
                    refresh_id,
                    err,
                    Some(repartition_restore),
                    connector_context,
                ),
            );
        }
        Err(err) => {
            return Err(
                handle_iceberg_mv_definite_pre_publish_error_with_repartition_restore(
                    state,
                    target,
                    target_entry,
                    staging_branch,
                    refresh_id,
                    err,
                    Some(repartition_restore),
                    connector_context,
                ),
            );
        }
    };
    let snapshots = ctx.rewrite.pin.to_snapshot_map();
    let table_uuids = ctx.rewrite.pin.to_table_uuid_map();
    record_iceberg_mv_staging_commit(
        state,
        refresh_id,
        commit_outcome.new_snapshot_id,
        total_rows,
        table_uuids.clone(),
    )?;
    let published_snapshot_id = resolve_iceberg_mv_publication(
        state,
        target,
        target_entry,
        staging_branch,
        refresh_id,
        Some(repartition_restore),
        connector_context,
        publish_iceberg_mv_refresh(
            state,
            target,
            target_entry,
            staging_branch,
            expected_main_snapshot_id,
            commit_outcome.new_snapshot_id,
            refresh_id,
            mv_definition.mv_id,
            connector_context,
        ),
    )?;
    record_iceberg_mv_publish_commit(state, refresh_id, published_snapshot_id)?;
    drop_iceberg_mv_staging_branch(
        state,
        target,
        target_entry,
        staging_branch,
        connector_context,
    )?;
    finalize_iceberg_mv_refresh_with_partition_contract(
        state,
        refresh_id,
        total_rows,
        snapshots,
        table_uuids,
        published_snapshot_id,
        partition_contract,
        IcebergMvPartitionStateFinalize::Clear,
    )
    .map_err(iceberg_mv_post_publish_finalize_error)?;
    Ok(StatementResult::Ok)
}

fn first_refresh_iceberg_join_mv(
    state: &Arc<StandaloneState>,
    ctx: &IcebergMvRefreshContext,
    staging_branch: &str,
    refresh_id: i64,
    left_ref: &TableIdentity,
    right_ref: &TableIdentity,
) -> Result<StatementResult, IcebergMvRefreshExecutionError> {
    let application_target = IcebergMvTarget::from(&ctx.rewrite.target);
    let target = &application_target;
    let target_entry = ctx.target_bindings.runtime().target_entry();
    let iceberg_catalog = &ctx.iceberg_catalog;
    let expected_main_snapshot_id = ctx.rewrite.target_snapshot_id;
    let connector_context = refresh_connector_context(ctx)?;
    if let Err(err) = ensure_iceberg_mv_staging_branch(
        state,
        iceberg_catalog,
        target,
        staging_branch,
        expected_main_snapshot_id,
        connector_context,
    ) {
        abort_iceberg_mv_refresh(state, refresh_id)?;
        return Err(err.into());
    }
    let target_table = match reload_iceberg_mv_target_table(target_entry, target) {
        Ok(table) => table,
        Err(err) => {
            return Err(handle_iceberg_mv_definite_pre_publish_error(
                state,
                target,
                target_entry,
                staging_branch,
                refresh_id,
                err,
                connector_context,
            ));
        }
    };
    let (plan, factory) = plan_canonical_select_for_imv(state, ctx).map_err(|err| {
        handle_iceberg_mv_commit_error(
            state,
            target,
            target_entry,
            staging_branch,
            refresh_id,
            err.message,
            connector_context,
        )
    })?;
    let logical_input =
        crate::mv::refresh::join_first_refresh::JoinFirstRefreshLogicalInput { plan, factory };
    let refresh_marker =
        load_iceberg_mv_refresh_marker(state, refresh_id, ctx.rewrite.mv_definition.mv_id)
            .map_err(|err| {
                handle_iceberg_mv_commit_error(
                    state,
                    target,
                    target_entry,
                    staging_branch,
                    refresh_id,
                    err,
                    connector_context,
                )
            })?;
    let mv_definition = &*ctx.rewrite.mv_definition;
    let marker = build_mv_refresh_provenance(
        &refresh_marker,
        RefreshTechnique::Full,
        build_mv_refresh_provenance_bases(
            &ctx.rewrite.pin.to_snapshot_map(),
            &ctx.rewrite.pin.to_table_uuid_map(),
            &mv_definition.last_refresh_snapshots,
        ),
        mv_definition_fingerprint(&mv_definition.select_sql),
        // TODO(W3a): thread exact row count. The join first-refresh row count
        // (`added_rows`) is only known after the change-stream write below, so
        // the watermark is stamped now and rows is left at 0.
        0,
    )
    .to_summary_properties()
    .map_err(|err| {
        handle_iceberg_mv_commit_error(
            state,
            target,
            target_entry,
            staging_branch,
            refresh_id,
            err,
            connector_context,
        )
    })?;
    let ident = iceberg_mv_table_ident(target).map_err(|err| {
        handle_iceberg_mv_commit_error(
            state,
            target,
            target_entry,
            staging_branch,
            refresh_id,
            err,
            connector_context,
        )
    })?;
    let target_backend = iceberg_mv_target_backend(target);
    let populated = crate::mv::refresh::join_first_refresh::execute_join_first_refresh_write(
        &target_table,
        &ident,
        staging_branch,
        &ctx.rewrite,
        left_ref,
        right_ref,
        logical_input,
        |logical| {
            let connectors_snapshot = state
                .connectors
                .read()
                .expect("standalone connector registry read lock")
                .clone();
            let planned_query = crate::engine::plan_logical_for_iceberg_change_stream_refresh(
                logical.plan,
                logical.factory,
                &connectors_snapshot,
            )?;
            execute_imv_change_stream_writer(
                state,
                &target_backend,
                &target_table,
                ImvRefreshPlannedChangeStream {
                    optimized_tree: planned_query.optimized_tree,
                    output_columns: planned_query.output_columns,
                    change_stream: logical.change_stream,
                    producer_branches: vec![ImvChangeStreamProducerBranch::FreshData],
                    mv_refresh_ctx: Some(ctx),
                },
                staging_branch,
            )
        },
    )
    .map_err(|err| {
        handle_iceberg_mv_commit_error(
            state,
            target,
            target_entry,
            staging_branch,
            refresh_id,
            err.into_message(),
            connector_context,
        )
    })?;

    let added_rows = match populated.effect {
        crate::mv::refresh::change_stream_write::ChangeStreamWriteEffect::Empty => 0,
        crate::mv::refresh::change_stream_write::ChangeStreamWriteEffect::Changed {
            added_rows,
            ..
        } => added_rows,
    };
    if matches!(
        populated.effect,
        crate::mv::refresh::change_stream_write::ChangeStreamWriteEffect::Empty
    ) {
        drop_iceberg_mv_staging_branch(
            state,
            target,
            target_entry,
            staging_branch,
            connector_context,
        )?;
        abort_iceberg_mv_refresh(state, refresh_id)?;
        return Ok(StatementResult::Ok);
    }
    let collector = populated.collector;
    let new_snapshot_id = match data_block_on(commit_iceberg_mv_with_populated_collector(
        &target_table,
        iceberg_catalog,
        target_entry,
        &ident,
        Arc::clone(&collector),
        staging_branch,
        marker,
    )) {
        Ok(Ok(outcome)) => outcome.new_snapshot_id,
        Ok(Err(err)) => {
            return Err(handle_iceberg_mv_commit_service_error(
                state,
                target,
                target_entry,
                staging_branch,
                refresh_id,
                err,
                connector_context,
            ));
        }
        Err(err) => {
            return Err(handle_iceberg_mv_definite_pre_publish_error(
                state,
                target,
                target_entry,
                staging_branch,
                refresh_id,
                err,
                connector_context,
            ));
        }
    };

    let snapshots = ctx.rewrite.pin.to_snapshot_map();
    let table_uuids = ctx.rewrite.pin.to_table_uuid_map();
    record_iceberg_mv_staging_commit(
        state,
        refresh_id,
        new_snapshot_id,
        added_rows,
        table_uuids.clone(),
    )?;
    let published_snapshot_id = resolve_iceberg_mv_publication(
        state,
        target,
        target_entry,
        staging_branch,
        refresh_id,
        None,
        connector_context,
        publish_iceberg_mv_refresh(
            state,
            target,
            target_entry,
            staging_branch,
            expected_main_snapshot_id,
            new_snapshot_id,
            refresh_id,
            ctx.rewrite.mv_definition.mv_id,
            connector_context,
        ),
    )?;
    record_iceberg_mv_publish_commit(state, refresh_id, published_snapshot_id)?;
    drop_iceberg_mv_staging_branch(
        state,
        target,
        target_entry,
        staging_branch,
        connector_context,
    )?;
    finalize_iceberg_mv_refresh(
        state,
        refresh_id,
        added_rows,
        snapshots,
        table_uuids,
        published_snapshot_id,
    )
    .map_err(iceberg_mv_post_publish_finalize_error)?;
    Ok(StatementResult::Ok)
}

fn rewrite_snapshot_table_factor(
    factor: &mut sqlparser::ast::TableFactor,
    base: &TableIdentity,
    snapshot_id: i64,
    default_alias: Option<&str>,
) -> Result<(), String> {
    let sqlparser::ast::TableFactor::Table {
        name,
        version,
        alias,
        args,
        ..
    } = factor
    else {
        return Err("join snapshot side must be a table".to_string());
    };
    if args.is_some() {
        return Err("join snapshot side must be a base table".to_string());
    }
    if !object_name_matches_base(name, base)? {
        return Err(format!(
            "join snapshot rewrite expected base {}, got {}",
            base.fqn(),
            name
        ));
    }
    if let Some(version) = version {
        let rendered = version.to_string();
        if !rendered.contains(&snapshot_id.to_string()) {
            return Err(format!(
                "join snapshot side {} has conflicting version {rendered}",
                base.fqn()
            ));
        }
    }
    *name = synthetic_snapshot_object_name(base, snapshot_id);
    *version = None;
    if alias.is_none()
        && let Some(default_alias) = default_alias
    {
        *alias = Some(sqlparser::ast::TableAlias {
            explicit: true,
            name: sqlparser::ast::Ident::new(default_alias),
            columns: Vec::new(),
        });
    }
    Ok(())
}

fn object_name_matches_base(
    name: &sqlparser::ast::ObjectName,
    base: &TableIdentity,
) -> Result<bool, String> {
    let parts = object_name_identifier_parts(name);
    Ok(match parts.as_slice() {
        [table] => table.eq_ignore_ascii_case(&base.table),
        [namespace, table] => {
            namespace.eq_ignore_ascii_case(&base.namespace)
                && table.eq_ignore_ascii_case(&base.table)
        }
        [catalog, namespace, table] => {
            catalog.eq_ignore_ascii_case(&base.catalog)
                && namespace.eq_ignore_ascii_case(&base.namespace)
                && table.eq_ignore_ascii_case(&base.table)
        }
        _ => false,
    })
}

fn object_name_identifier_parts(name: &sqlparser::ast::ObjectName) -> Vec<String> {
    name.0
        .iter()
        .filter_map(|part| match part {
            sqlparser::ast::ObjectNamePart::Identifier(ident) => Some(ident.value.clone()),
            _ => None,
        })
        .collect()
}

fn synthetic_snapshot_table_name(base: &TableIdentity, snapshot_id: i64) -> String {
    format!("{}__at_{}", base.table, snapshot_id)
}

fn synthetic_snapshot_object_name(
    base: &TableIdentity,
    snapshot_id: i64,
) -> sqlparser::ast::ObjectName {
    sqlparser::ast::ObjectName(vec![
        sqlparser::ast::ObjectNamePart::Identifier(sqlparser::ast::Ident::new(&base.namespace)),
        sqlparser::ast::ObjectNamePart::Identifier(sqlparser::ast::Ident::new(
            synthetic_snapshot_table_name(base, snapshot_id),
        )),
    ])
}

fn build_join_snapshot_catalog(
    state: &Arc<StandaloneState>,
    snapshots: &[(&TableIdentity, i64); 2],
) -> Result<crate::sql::catalog::local::PlannerMemoryCatalog, String> {
    let mut catalog = crate::sql::catalog::local::PlannerMemoryCatalog::default();
    for (base, snapshot_id) in snapshots {
        register_join_snapshot_side(&mut catalog, state, base, *snapshot_id)?;
    }
    Ok(catalog)
}

/// Build a one-shot InMemoryCatalog for IMV optimizer-pipeline planning.
///
/// Registers each base in `ctx.rewrite.base_refs` under its namespace at
/// the snapshot captured by `ctx.rewrite.pin`. The catalog mirrors what
/// `canonical_select_query` references after `canonicalize_iceberg_mv_select_query`
/// rewrites `db.table` to `db.<synthetic>_at_<snapshot_id>`.
///
/// Reuses `build_iceberg_table_def_for_snapshot_scan` for per-base
/// table-def construction, so schemas / partition specs match what the
/// existing snapshot-scan path already uses.
fn build_iceberg_mv_planning_catalog(
    state: &Arc<StandaloneState>,
    ctx: &IcebergMvRefreshContext,
) -> Result<crate::sql::catalog::local::PlannerMemoryCatalog, String> {
    let mut catalog = crate::sql::catalog::local::PlannerMemoryCatalog::default();

    for base in ctx.rewrite.base_refs.iter() {
        let snapshot_id = ctx.rewrite.pin.get(base).ok_or_else(|| {
            format!(
                "imv planning catalog: pin missing snapshot for base {}",
                base.fqn()
            )
        })?;

        // create_database is idempotent-ish: it errors on duplicate. Two
        // bases sharing a namespace must only create the database once.
        if !catalog.database_exists(&base.namespace).map_err(|e| {
            format!(
                "imv planning catalog: database_exists({}): {e}",
                base.namespace
            )
        })? {
            catalog.create_database(&base.namespace).map_err(|e| {
                format!(
                    "imv planning catalog: create_database({}): {e}",
                    base.namespace
                )
            })?;
        }

        let mut table_def = build_iceberg_table_def_for_snapshot_scan(state, base, snapshot_id)?;
        // build_iceberg_table_def_for_snapshot_scan names the table with a
        // synthetic <table>__at_<snapshot_id> suffix used by the hand-built
        // join refresh path. The IMV planning catalog instead registers
        // each base under its ORIGINAL name because
        // canonicalize_iceberg_mv_select_query only adds a catalog prefix
        // (it does not rewrite table identifiers to synthetic snapshot
        // names). The snapshot pin is preserved implicitly via the table
        // def's data files extracted at snapshot_id.
        table_def.name = base.table.clone();
        catalog
            .register(&base.namespace, table_def)
            .map_err(|e| format!("imv planning catalog: register {}: {e}", base.fqn()))?;
    }

    Ok(catalog)
}

fn register_join_snapshot_side(
    catalog: &mut crate::sql::catalog::local::PlannerMemoryCatalog,
    state: &Arc<StandaloneState>,
    base: &TableIdentity,
    snapshot_id: i64,
) -> Result<(), String> {
    catalog.create_database(&base.namespace)?;
    let table_def = build_iceberg_table_def_for_snapshot_scan(state, base, snapshot_id)?;
    catalog
        .register(&base.namespace, table_def)
        .map_err(|e| format!("register join snapshot table {}: {e}", base.fqn()))
}

/// Re-plan ctx.rewrite.canonical_select_query into a LogicalPlanNode suitable
/// for handing to `run_imv_rewrite`.
///
/// Failure here is fail-fast: if the canonical SELECT cannot be analyzed
/// or planned, the refresh attempt aborts. This deliberately surfaces
/// canonicalization bugs early rather than tolerating divergence between
/// today's hand-built refresh path and the IMV pipeline.
fn plan_canonical_select_for_imv(
    state: &Arc<StandaloneState>,
    ctx: &IcebergMvRefreshContext,
) -> Result<
    (
        crate::sql::planner::logical::LogicalPlanNode,
        crate::sql::column_id::ColumnRefFactory,
    ),
    RefreshError,
> {
    let catalog = build_iceberg_mv_planning_catalog(state, ctx).map_err(|e| {
        RefreshError::user(format!(
            "imv plan failed for {}.{}.{}: build planning catalog: {e}",
            ctx.rewrite.target.catalog, ctx.rewrite.target.namespace, ctx.rewrite.target.table
        ))
    })?;

    let (resolved, cte_registry, mut factory) = crate::sql::analyzer::analyze(
        ctx.rewrite.canonical_select_query.as_ref(),
        &catalog,
        &ctx.rewrite.current_database,
    )
    .map_err(|e| {
        RefreshError::user(format!(
            "imv plan failed for {}.{}.{}: analyze: {e}",
            ctx.rewrite.target.catalog, ctx.rewrite.target.namespace, ctx.rewrite.target.table
        ))
    })?;

    let plan =
        crate::sql::planner::plan_query(resolved, cte_registry, &mut factory).map_err(|e| {
            RefreshError::user(format!(
                "imv plan failed for {}.{}.{}: plan_query: {e}",
                ctx.rewrite.target.catalog, ctx.rewrite.target.namespace, ctx.rewrite.target.table
            ))
        })?;
    Ok((normalize_imv_rewrite_root_project(plan), factory))
}

pub(crate) fn normalize_imv_rewrite_root_project(
    plan: crate::sql::planner::logical::LogicalPlanNode,
) -> crate::sql::planner::logical::LogicalPlanNode {
    use crate::sql::planner::logical::{LogicalPlanKind, LogicalPlanNode};

    let LogicalPlanNode {
        kind,
        mut children,
        required_output_columns,
    } = plan;
    let LogicalPlanKind::Project(project) = kind else {
        return LogicalPlanNode::new(kind, children, required_output_columns);
    };
    let input = children.remove(0);
    let LogicalPlanNode {
        kind: input_kind,
        children: aggregate_children,
        required_output_columns: aggregate_required_output_columns,
    } = input;
    let LogicalPlanKind::Aggregate(mut aggregate) = input_kind else {
        let input = LogicalPlanNode::new(
            input_kind,
            aggregate_children,
            aggregate_required_output_columns,
        );
        return LogicalPlanNode::new(
            LogicalPlanKind::Project(project),
            vec![input],
            required_output_columns,
        );
    };
    if project.items.len() != aggregate.output_columns.len() {
        let input = LogicalPlanNode::new(
            LogicalPlanKind::Aggregate(aggregate),
            aggregate_children,
            aggregate_required_output_columns,
        );
        return LogicalPlanNode::new(
            LogicalPlanKind::Project(project),
            vec![input],
            required_output_columns,
        );
    }
    let Some(output_columns) = project
        .items
        .iter()
        .zip(aggregate.output_columns.iter())
        .map(|item| {
            let (item, aggregate_output) = item;
            let ExprKind::ColumnRef { column_id, .. } = &item.expr.kind else {
                return None;
            };
            if *column_id != aggregate_output.column_id {
                return None;
            }
            Some(crate::sql::analysis::OutputColumn {
                column_id: *column_id,
                name: item.output_name.clone(),
                data_type: item.expr.data_type.clone(),
                nullable: item.expr.nullable,
                is_internal: false,
            })
        })
        .collect::<Option<Vec<_>>>()
    else {
        let input = LogicalPlanNode::new(
            LogicalPlanKind::Aggregate(aggregate),
            aggregate_children,
            aggregate_required_output_columns,
        );
        return LogicalPlanNode::new(
            LogicalPlanKind::Project(project),
            vec![input],
            required_output_columns,
        );
    };
    aggregate.output_columns = output_columns;
    LogicalPlanNode::new(
        LogicalPlanKind::Aggregate(aggregate),
        aggregate_children,
        aggregate_required_output_columns,
    )
}

/// Run the IMV optimizer pipeline for EXPLAIN. Refresh execution wires the
/// pipeline through `execute_query_with_options_and_imv_validator`, where
/// aggregate and join aggregate rewrite failures remain fatal.
fn run_imv_rewrite_for_refresh_explain(
    state: &Arc<StandaloneState>,
    ctx: &IcebergMvRefreshContext,
) -> Result<crate::sql::planner::imv_rewrite::entrypoint::ImvRewriteOutcome, String> {
    let (plan, factory) = plan_canonical_select_for_imv(state, ctx).map_err(|e| e.message)?;
    let factory_cell = std::rc::Rc::new(std::cell::RefCell::new(factory));
    // Thread the active session's disable_optimizer_rules into IMV. When
    // refresh runs outside a user session (e.g. background scheduler),
    // the thread-local default is empty, so this is a safe no-op.
    let disabled_rules = refresh_explain_rewrite_disabled_rules(
        ctx.rewrite.schema_contract.aggregate.is_some(),
        &crate::sql::optimizer::options::SessionOptimizerSettings::default(),
    );
    let outcome = crate::sql::planner::imv_rewrite::entrypoint::run_imv_rewrite(
        crate::sql::planner::imv_rewrite::entrypoint::ImvRewriteInput {
            plan,
            mv_ctx: Arc::clone(&ctx.rewrite),
            disabled_rules,
            deadline: None,
            column_ref_factory: std::rc::Rc::clone(&factory_cell),
        },
    )
    .map_err(|e| format!("run_imv_rewrite: {e}"))?;
    let _factory = std::rc::Rc::try_unwrap(factory_cell)
        .map_err(|_| "IMV rewrite leaked ColumnRefFactory references".to_string())?
        .into_inner();
    Ok(outcome)
}

fn refresh_explain_rewrite_disabled_rules(
    is_aggregate_refresh: bool,
    optimizer_settings: &crate::sql::optimizer::options::SessionOptimizerSettings,
) -> Vec<String> {
    let mut disabled_rules = optimizer_settings.disabled_rules.clone();
    if is_aggregate_refresh
        && !disabled_rules
            .iter()
            .any(|rule| rule == "RecordJoinRefreshDescriptor")
    {
        disabled_rules.push("RecordJoinRefreshDescriptor".to_string());
    }
    disabled_rules
}

fn validate_aggregate_refresh_rewrite_outcome(
    ctx: &crate::mv::rewrite::context::IcebergMvRewriteContext,
    outcome: &crate::sql::planner::imv_rewrite::entrypoint::ImvRewriteOutcome,
    evidence: RewriteMergeRefreshEvidence,
) -> Result<(), String> {
    if evidence == RewriteMergeRefreshEvidence::JoinAggregate
        && !rewrite_outcome_rule_changed(outcome, "RewriteJoinDelta")
    {
        return Err(format!(
            "iceberg join aggregate MV {} incremental refresh rewrite did not apply RewriteJoinDelta",
            ctx.target.fqn()
        ));
    }
    if evidence == RewriteMergeRefreshEvidence::BranchUnionAggregate
        && !rewrite_outcome_rule_changed(outcome, "RewriteBranchUnion")
    {
        return Err(format!(
            "iceberg branch UNION ALL aggregate MV {} incremental refresh rewrite did not apply RewriteBranchUnion",
            ctx.target.fqn()
        ));
    }
    if evidence != RewriteMergeRefreshEvidence::BranchUnionAggregate
        && !rewrite_outcome_rule_changed(outcome, "RewriteAggregateState")
    {
        let label = match evidence {
            RewriteMergeRefreshEvidence::JoinAggregate => "join aggregate",
            _ => "aggregate",
        };
        return Err(format!(
            "iceberg {label} MV {} incremental refresh rewrite did not apply RewriteAggregateState",
            ctx.target.fqn()
        ));
    }
    if !outcome.annotation.change_stream.has_aggregate() {
        let label = match evidence {
            RewriteMergeRefreshEvidence::JoinAggregate => "join aggregate",
            RewriteMergeRefreshEvidence::BranchUnionAggregate => "branch UNION ALL aggregate",
            _ => "aggregate",
        };
        return Err(format!(
            "iceberg {label} MV {} incremental refresh rewrite plan does not contain aggregate state change stream",
            ctx.target.fqn()
        ));
    }
    tracing::info!(
        mv_target = ?ctx.target,
        mv_id = ctx.mv_id,
        stages = ?outcome.trace.stage_names(),
        "iceberg aggregate MV incremental refresh rewrite evidence validated"
    );
    Ok(())
}

fn rewrite_outcome_rule_changed(
    outcome: &crate::sql::planner::imv_rewrite::entrypoint::ImvRewriteOutcome,
    rule_name: &str,
) -> bool {
    outcome.trace.events().iter().any(|event| {
        matches!(
            event,
            crate::sql::optimizer::rewrite::trace::RewriteTraceEvent::RuleChanged { rule, .. }
                if *rule == rule_name
        )
    })
}

#[cfg(test)]
mod partition_planning_tests {
    use super::*;
    use mv_schema::{
        ApplyKeySource, BaseContract, BaseFieldRecord, BaseSchemaSnapshot, ExpressionKind,
        ExpressionLineage, HiddenApplyKeyContract, MvPartitionContract, MvPartitionFieldContract,
        MvPartitionTransformContract, MvSchemaContract, OutputColumnLineage, OutputContract,
        TargetContract, TargetVisibleColumn,
    };

    fn key(value: &str) -> crate::mv::model::MvPartitionKey {
        crate::mv::model::MvPartitionKey::new(
            7,
            vec![crate::mv::model::MvPartitionKeyField::new(
                "region".to_string(),
                crate::mv::model::MvPartitionValue::String(value.to_string()),
            )],
        )
    }

    fn base_ref(table: &str) -> TableIdentity {
        TableIdentity {
            catalog: "ice".to_string(),
            namespace: "db".to_string(),
            table: table.to_string(),
        }
    }

    fn contract_with_identity_partition() -> MvSchemaContract {
        MvSchemaContract {
            contract_version: 1,
            base: BaseContract {
                table_fqn: "ice.db.left".to_string(),
                table_uuid: "base-uuid".to_string(),
                alias_at_create: None,
                schema_id_at_create: 0,
                schema_at_create: BaseSchemaSnapshot {
                    fields: vec![BaseFieldRecord {
                        field_id: 1,
                        name_at_create: "id".to_string(),
                        type_signature: "int".to_string(),
                        required: true,
                    }],
                },
            },
            bases: Vec::new(),
            output: OutputContract {
                columns: vec![OutputColumnLineage {
                    expression: ExpressionLineage {
                        kind: ExpressionKind::Column,
                        referenced_base_field_ids: vec![1],
                        referenced_base_fields: Vec::new(),
                    },
                }],
                filter: None,
            },
            join: None,
            aggregate: None,
            branch: None,
            target: TargetContract {
                table_fqn: "ice.db.mv".to_string(),
                table_uuid: "target-uuid".to_string(),
                schema_id_at_create: 0,
                visible_columns: vec![TargetVisibleColumn {
                    output_name: "id".to_string(),
                    target_field_id: 10,
                    type_signature: "int".to_string(),
                    nullable: false,
                }],
                hidden_apply_key: HiddenApplyKeyContract {
                    column_name: "__nova_base_row_id".to_string(),
                    target_field_id: 11,
                    source: ApplyKeySource::BaseRowId,
                },
                partition: Some(MvPartitionContract {
                    target_spec_id: 7,
                    fields: vec![MvPartitionFieldContract {
                        partition_field_id: 100,
                        partition_field_name: "id".to_string(),
                        source_target_field_id: 10,
                        source_column_name: "id".to_string(),
                        transform: MvPartitionTransformContract::Identity,
                    }],
                }),
            },
        }
    }

    #[test]
    fn merge_affected_partition_results_unions_known_sets() {
        let merged = merge_affected_partition_results(
            "UNION ALL MV affected partition planning",
            vec![
                (
                    "ice.db.left".to_string(),
                    crate::mv::model::AffectedTargetPartitions::known([key("west"), key("east")]),
                ),
                (
                    "ice.db.right".to_string(),
                    crate::mv::model::AffectedTargetPartitions::known([key("east"), key("north")]),
                ),
            ],
        );

        assert_eq!(
            merged,
            crate::mv::model::AffectedTargetPartitions::known([
                key("east"),
                key("north"),
                key("west"),
            ])
        );
    }

    #[test]
    fn merge_affected_partition_results_preserves_first_not_derived_reason() {
        let merged = merge_affected_partition_results(
            "UNION ALL MV affected partition planning",
            vec![
                (
                    "ice.db.left".to_string(),
                    crate::mv::model::AffectedTargetPartitions::known([key("west")]),
                ),
                (
                    "ice.db.right".to_string(),
                    crate::mv::model::AffectedTargetPartitions::not_derived(
                        "missing file partition metadata",
                    ),
                ),
            ],
        );

        assert_eq!(
            merged.not_derived_reason(),
            Some(
                "UNION ALL MV affected partition planning: ice.db.right: missing file partition metadata"
            )
        );
    }

    #[test]
    fn plan_multi_base_affected_partitions_unchanged_bases_return_empty_known_set() {
        let contract = contract_with_identity_partition();
        let base_refs = vec![base_ref("left"), base_ref("right")];
        let previous_snapshots = BTreeMap::from([
            ("ice.db.left".to_string(), 11_i64),
            ("ice.db.right".to_string(), 22_i64),
        ]);
        let current_snapshots = BTreeMap::from([
            ("ice.db.left".to_string(), Some(11_i64)),
            ("ice.db.right".to_string(), Some(22_i64)),
        ]);

        let planned = plan_multi_base_affected_partitions(
            &contract,
            RefreshMode::Incremental,
            &base_refs,
            &previous_snapshots,
            &current_snapshots,
            |_base_ref| panic!("unchanged bases should not require loaded table lookup"),
            "UNION ALL MV affected partition planning",
        );

        assert_eq!(
            planned,
            crate::mv::model::AffectedTargetPartitions::known(std::iter::empty::<
                crate::mv::model::MvPartitionKey,
            >(),)
        );
    }
}

#[cfg(test)]
mod aggregate_refresh_rewrite_validation_tests {
    use super::*;

    use crate::sql::column_id::ColumnId;
    use crate::sql::optimizer::rewrite::phase::RewritePhase;
    use crate::sql::optimizer::rewrite::trace::RewriteTrace;
    use crate::sql::planner::imv_rewrite::annotation::ImvPlanAnnotation;
    use crate::sql::planner::imv_rewrite::change_stream::{
        AggregateChangeStreamDescriptor, AggregateChangeStreamShape, ImvChangeStreamDescriptor,
        SignedStateAggregateProof, TargetStateProof,
    };
    use crate::sql::planner::imv_rewrite::entrypoint::ImvRewriteOutcome;
    use crate::sql::planner::logical::{LogicalPlanKind, LogicalPlanNode};
    use crate::sql::planner::payload::PlanValuesNode;

    fn empty_values_plan() -> LogicalPlanNode {
        LogicalPlanNode::new(
            LogicalPlanKind::Values(PlanValuesNode {
                rows: Vec::new(),
                columns: Vec::new(),
            }),
            vec![],
            None,
        )
    }

    fn outcome(plan: LogicalPlanNode, changed_rules: &[&'static str]) -> ImvRewriteOutcome {
        let mut trace = RewriteTrace::default();
        for rule in changed_rules {
            trace.rule_changed(RewritePhase::SemanticRewrite, rule, 0);
        }
        ImvRewriteOutcome {
            plan,
            trace,
            annotation: ImvPlanAnnotation::default(),
        }
    }

    fn aggregate_change_stream_descriptor() -> ImvChangeStreamDescriptor {
        ImvChangeStreamDescriptor {
            aggregate: Some(AggregateChangeStreamDescriptor {
                action_column_id: ColumnId::new_for_test(1),
                action_column_name: crate::exec::change_op::CHANGE_OP_COLUMN.to_string(),
                shape: AggregateChangeStreamShape::UnionChangeStream,
                target_state: TargetStateProof { present: true },
                signed_state_aggregate: SignedStateAggregateProof { present: true },
            }),
            ..Default::default()
        }
    }

    fn outcome_with_aggregate_descriptor(
        plan: LogicalPlanNode,
        changed_rules: &[&'static str],
    ) -> ImvRewriteOutcome {
        let mut outcome = outcome(plan, changed_rules);
        outcome.annotation.change_stream = aggregate_change_stream_descriptor();
        outcome
    }

    #[test]
    fn aggregate_refresh_rejects_unchanged_rewrite_outcome() {
        let ctx = crate::mv::rewrite::context::tests_support::dummy_rewrite_context();
        let outcome = outcome(empty_values_plan(), &[]);

        let err = validate_aggregate_refresh_rewrite_outcome(
            &ctx,
            &outcome,
            RewriteMergeRefreshEvidence::Aggregate,
        )
        .expect_err("aggregate refresh must not continue with unchanged rewrite outcome");

        assert!(
            err.contains("did not apply RewriteAggregateState"),
            "got: {err}"
        );
    }

    #[test]
    fn aggregate_refresh_rejects_missing_merge_plan_evidence() {
        let ctx = crate::mv::rewrite::context::tests_support::dummy_rewrite_context();
        let outcome = outcome(empty_values_plan(), &["RewriteAggregateState"]);

        let err = validate_aggregate_refresh_rewrite_outcome(
            &ctx,
            &outcome,
            RewriteMergeRefreshEvidence::Aggregate,
        )
        .expect_err("aggregate refresh must require change stream in the rewrite plan");

        assert!(
            err.contains("does not contain aggregate state change stream"),
            "got: {err}"
        );
    }

    #[test]
    fn join_aggregate_refresh_rejects_missing_join_rewrite_evidence() {
        let ctx = crate::mv::rewrite::context::tests_support::dummy_rewrite_context();
        let outcome =
            outcome_with_aggregate_descriptor(empty_values_plan(), &["RewriteAggregateState"]);

        let err = validate_aggregate_refresh_rewrite_outcome(
            &ctx,
            &outcome,
            RewriteMergeRefreshEvidence::JoinAggregate,
        )
        .expect_err("join aggregate refresh must require join rewrite evidence");

        assert!(err.contains("did not apply RewriteJoinDelta"), "got: {err}");
    }

    #[test]
    fn join_aggregate_refresh_missing_merge_plan_uses_join_label() {
        let ctx = crate::mv::rewrite::context::tests_support::dummy_rewrite_context();
        let outcome = outcome(
            empty_values_plan(),
            &["RewriteJoinDelta", "RewriteAggregateState"],
        );

        let err = validate_aggregate_refresh_rewrite_outcome(
            &ctx,
            &outcome,
            RewriteMergeRefreshEvidence::JoinAggregate,
        )
        .expect_err("join aggregate refresh must require change stream in the rewrite plan");

        assert!(
            err.contains("iceberg join aggregate MV")
                && err.contains("does not contain aggregate state change stream"),
            "got: {err}"
        );
    }

    #[test]
    fn branch_union_aggregate_refresh_rejects_missing_branch_union_rewrite_evidence() {
        let ctx = crate::mv::rewrite::context::tests_support::dummy_rewrite_context();
        let outcome =
            outcome_with_aggregate_descriptor(empty_values_plan(), &["RewriteAggregateState"]);

        let err = validate_aggregate_refresh_rewrite_outcome(
            &ctx,
            &outcome,
            RewriteMergeRefreshEvidence::BranchUnionAggregate,
        )
        .expect_err("branch UNION ALL aggregate refresh must require branch rewrite evidence");

        assert!(
            err.contains("branch UNION ALL aggregate")
                && err.contains("did not apply RewriteBranchUnion"),
            "got: {err}"
        );
    }

    #[test]
    fn branch_union_aggregate_refresh_requires_state_merge_plan_evidence() {
        let ctx = crate::mv::rewrite::context::tests_support::dummy_rewrite_context();
        let outcome = outcome(empty_values_plan(), &["RewriteBranchUnion"]);

        let err = validate_aggregate_refresh_rewrite_outcome(
            &ctx,
            &outcome,
            RewriteMergeRefreshEvidence::BranchUnionAggregate,
        )
        .expect_err("branch UNION ALL aggregate refresh must require change-stream plan evidence");

        assert!(
            err.contains("iceberg branch UNION ALL aggregate MV")
                && err.contains("does not contain aggregate state change stream"),
            "got: {err}"
        );
    }

    #[test]
    fn branch_union_aggregate_refresh_accepts_branch_rewrite_with_change_stream_plan() {
        let ctx = crate::mv::rewrite::context::tests_support::dummy_rewrite_context();
        let outcome =
            outcome_with_aggregate_descriptor(empty_values_plan(), &["RewriteBranchUnion"]);

        validate_aggregate_refresh_rewrite_outcome(
            &ctx,
            &outcome,
            RewriteMergeRefreshEvidence::BranchUnionAggregate,
        )
        .expect(
            "branch UNION ALL aggregate refresh should accept branch rewrite with aggregate-state change-stream evidence",
        );
    }

    #[test]
    fn aggregate_refresh_accepts_change_stream_descriptor_evidence() {
        let ctx = crate::mv::rewrite::context::tests_support::dummy_rewrite_context();
        let outcome =
            outcome_with_aggregate_descriptor(empty_values_plan(), &["RewriteAggregateState"]);

        validate_aggregate_refresh_rewrite_outcome(
            &ctx,
            &outcome,
            RewriteMergeRefreshEvidence::Aggregate,
        )
        .expect(
            "aggregate refresh should accept aggregate-state change-stream descriptor evidence",
        );
    }

    #[test]
    fn aggregate_refresh_source_does_not_use_legacy_sql_delta_path() {
        let source = std::fs::read_to_string(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/src/engine/mv/iceberg_refresh.rs"
        ))
        .expect("read source");
        let forbidden = [
            concat!("execute_delta_source_", "query"),
            concat!("iceberg_aggregate_incremental_", "delta_select_sql"),
            concat!("incremental_refresh_iceberg_", "aggregate_mv"),
        ];

        for token in forbidden {
            assert!(
                !source.contains(token),
                "legacy aggregate refresh SQL delta path remains: {token}"
            );
        }
    }
}

#[cfg(test)]
mod join_delta_append_only_fast_path_tests {
    use super::*;

    #[test]
    fn join_incremental_refresh_plan_kind_uses_logical_cutover() {
        let mode = select_join_incremental_refresh_mode(false, false);
        assert_eq!(mode, JoinIncrementalRefreshMode::AppendOnly);
        let mode = select_join_incremental_refresh_mode(true, false);
        assert_eq!(mode, JoinIncrementalRefreshMode::Coalesce);
        let mode = select_join_incremental_refresh_mode(false, true);
        assert_eq!(mode, JoinIncrementalRefreshMode::Coalesce);
    }

    #[test]
    fn aggregate_refresh_explain_disables_join_refresh_descriptor_recording() {
        let disabled_rules = refresh_explain_rewrite_disabled_rules(
            true,
            &crate::sql::optimizer::options::SessionOptimizerSettings::default(),
        );

        assert!(
            disabled_rules
                .iter()
                .any(|rule| rule == "RecordJoinRefreshDescriptor"),
            "aggregate refresh explain must not record a pure join refresh descriptor"
        );
    }

    #[test]
    fn join_delta_append_only_fast_path_requires_append_only_inner_or_cross_join() {
        assert!(should_use_join_delta_append_only_fast_path(
            &parse_query("select l.id from ice.ns.left l join ice.ns.right r on l.id = r.id"),
            false,
            false,
        ));
        assert!(should_use_join_delta_append_only_fast_path(
            &parse_query("select l.id from ice.ns.left l cross join ice.ns.right r"),
            false,
            false,
        ));

        assert!(!should_use_join_delta_append_only_fast_path(
            &parse_query("select l.id from ice.ns.left l join ice.ns.right r on l.id = r.id"),
            true,
            false,
        ));
        assert!(!should_use_join_delta_append_only_fast_path(
            &parse_query("select l.id from ice.ns.left l join ice.ns.right r on l.id = r.id"),
            false,
            true,
        ));
        assert!(!should_use_join_delta_append_only_fast_path(
            &parse_query("select l.id from ice.ns.left l left join ice.ns.right r on l.id = r.id"),
            false,
            false,
        ));
    }

    #[test]
    fn join_delta_coalesce_uses_normalized_snapshot_ctes() {
        let base_query = parse_query(
            "select l.id, r.label from ice.ns.left l join ice.ns.right r on l.id = r.id",
        );
        let left = base("left");
        let right = base("right");
        let branches = crate::engine::mv::iceberg_join_branch::plan_join_delta_branches(
            &left,
            &right,
            crate::engine::mv::iceberg_join_branch::SnapshotWindow { from: 10, to: 11 },
            crate::engine::mv::iceberg_join_branch::SnapshotWindow { from: 20, to: 21 },
            true,
            true,
        );
        let mut branch_queries = Vec::new();
        for branch in &branches {
            let mut branch_query =
                crate::engine::mv::iceberg_join_branch::rewrite_join_branch_query(
                    &base_query,
                    branch,
                    "l",
                    "r",
                )
                .expect("branch rewrite");
            normalize_join_branch_snapshot_tables(&mut branch_query, branch)
                .expect("snapshot normalization");
            branch_queries.push(branch_query);
        }

        let coalesced =
            crate::engine::mv::iceberg_join_branch::rewrite_join_delta_coalesce_query_with_branch_queries(
                &base_query,
                branch_queries,
                "left-uuid",
                "right-uuid",
            )
            .expect("coalesce rewrite");
        let rendered = coalesced.to_string();

        assert!(rendered.contains("right__at_20"), "sql={rendered}");
        assert!(rendered.contains("left__at_11"), "sql={rendered}");
        assert!(!rendered.contains("VERSION AS OF"), "sql={rendered}");
        assert!(
            rendered.contains("__nr_join_delta_branch_0"),
            "sql={rendered}"
        );
        assert!(
            rendered.contains("__nr_join_delta_branch_1"),
            "sql={rendered}"
        );
    }

    fn base(name: &str) -> TableIdentity {
        TableIdentity {
            catalog: "ice".to_string(),
            namespace: "ns".to_string(),
            table: name.to_string(),
        }
    }

    fn parse_query(sql: &str) -> sqlparser::ast::Query {
        let normalized =
            crate::sql::parser::dialect::normalize_for_raw_parse(sql).expect("normalize");
        let stmt = crate::sql::parser::parse_normalized_sql_raw(&normalized).expect("parse");
        let sqlparser::ast::Statement::Query(query) = stmt else {
            panic!("expected query");
        };
        *query
    }
}

pub(crate) fn explain_iceberg_mv_refresh_rewrite_plan(
    state: &Arc<StandaloneState>,
    current_catalog: Option<&str>,
    current_database: &str,
    stmt: &RefreshMaterializedViewStmt,
    level: crate::sql::explain::ExplainLevel,
) -> Result<Vec<String>, String> {
    explain_refresh_full_guard(stmt.full)?;

    let target = resolve_refresh_target(current_catalog, current_database, &stmt.name)?;
    let mv_definition = load_iceberg_mv_definition_by_target(state, &target)?;
    let (target_entry, iceberg_catalog, target_loaded) = load_iceberg_mv_target(state, &target)?;
    validate_target_snapshot(&target, &mv_definition, &target_loaded.table)?;

    let base_refs = parse_iceberg_table_refs(&mv_definition.base_table_refs)?;
    let canonical_select_query = canonicalize_iceberg_mv_select_query(
        &parse_mv_select_query(&mv_definition.select_sql)?,
        current_catalog,
        current_database,
    );
    // Capability-driven (not classifier-driven): the aggregate metadata
    // validation runs when the persisted contract carries an aggregate state.
    // Deriving this from the schema contract instead of re-classifying the
    // SELECT keeps EXPLAIN REFRESH working for composed branch-union shapes
    // whose branches contain joins (the legacy classifier rejects those).
    let dispatch_schema_contract = mv_definition.schema_contract.as_ref().ok_or_else(|| {
        format!(
            "iceberg MV target {}.{}.{} is missing A11 schema contract; rebuild or recreate the MV",
            target.catalog, target.namespace, target.table
        )
    })?;
    if RefreshCapabilities::from_schema_contract(dispatch_schema_contract)?.has_agg_state {
        validate_aggregate_schema_contract_metadata(&target, &mv_definition)?;
    }

    let pin = capture_refresh_snapshot_pin(state, &base_refs)?;
    validate_refresh_pin_table_uuids(&mv_definition, &pin, &base_refs)?;

    let ctx = {
        let iceberg_catalog_guard = state
            .iceberg_catalogs
            .read()
            .map_err(|e| format!("iceberg catalog registry read lock: {e}"))?;
        IcebergMvRefreshContext::new_with_pruning_limits(
            TableIdentity {
                catalog: target.catalog,
                namespace: target.namespace,
                table: target.table,
            },
            mv_definition.mv_id,
            current_catalog,
            current_database,
            Arc::new(mv_definition),
            Arc::new(canonical_select_query),
            Arc::from(base_refs),
            Arc::new(pin),
            &iceberg_catalog_guard,
            Arc::new(target_entry),
            iceberg_catalog,
            target_loaded.table,
            state.mv_refresh_pruning_limits,
        )?
    };
    let outcome = run_imv_rewrite_for_refresh_explain(state, &ctx)?;
    crate::sql::explain::explain_plan_checked(&outcome.plan, level)
}

fn build_iceberg_table_def_for_snapshot_scan(
    state: &Arc<StandaloneState>,
    base: &TableIdentity,
    snapshot_id: i64,
) -> Result<crate::sql::planner::table::TableDef, String> {
    let entry = {
        let registry = state
            .iceberg_catalogs
            .read()
            .map_err(|e| format!("iceberg catalog registry read lock: {e}"))?;
        registry.get(&base.catalog)?
    };
    let loaded =
        crate::connector::iceberg::catalog::load_table(&entry, &base.namespace, &base.table)?;
    let data_files =
        crate::connector::iceberg::catalog::registry::extract_data_files_with_stats_at(
            &loaded.table,
            snapshot_id,
        )?;
    let synthetic_name = synthetic_snapshot_table_name(base, snapshot_id);
    if data_files.is_empty() {
        let mut table_def =
            crate::connector::iceberg::catalog::build_iceberg_table_def_for_delta_scan(
                &base.catalog,
                &base.namespace,
                &base.table,
                loaded,
            )?;
        table_def.name = synthetic_name;
        table_def
            .iceberg_row_lineage_metadata_columns
            .retain(|column| column.name != crate::exec::change_op::CHANGE_OP_COLUMN);
        return Ok(table_def);
    }
    let mut table_def = crate::connector::iceberg::catalog::build_iceberg_table_def_with_files(
        &entry,
        &base.catalog,
        &base.namespace,
        &base.table,
        loaded,
        data_files,
    )?;
    table_def.name = synthetic_name;
    Ok(table_def)
}

fn incremental_refresh_iceberg_join_mv(
    state: &Arc<StandaloneState>,
    ctx: &IcebergMvRefreshContext,
    base_refs: &[TableIdentity],
) -> Result<StatementResult, IcebergMvRefreshExecutionError> {
    let application_target = IcebergMvTarget::from(&ctx.rewrite.target);
    let target = &application_target;
    let mv_definition = &*ctx.rewrite.mv_definition;
    let pin = &*ctx.rewrite.pin;
    if base_refs.len() != 2 {
        return Err("iceberg join MV refresh requires exactly two base tables"
            .to_string()
            .into());
    }
    let left_ref = &base_refs[0];
    let right_ref = &base_refs[1];
    let left_to = pin
        .get(left_ref)
        .ok_or_else(|| format!("missing pin for {}", left_ref.fqn()))?;
    let right_to = pin
        .get(right_ref)
        .ok_or_else(|| format!("missing pin for {}", right_ref.fqn()))?;
    let left_from = mv_definition
        .last_refresh_snapshots
        .get(&left_ref.fqn())
        .copied()
        .ok_or_else(|| {
            format!(
                "join MV {} missing previous snapshot for {}",
                mv_definition.mv_id,
                left_ref.fqn()
            )
        })?;
    let right_from = mv_definition
        .last_refresh_snapshots
        .get(&right_ref.fqn())
        .copied()
        .ok_or_else(|| {
            format!(
                "join MV {} missing previous snapshot for {}",
                mv_definition.mv_id,
                right_ref.fqn()
            )
        })?;
    let left_loaded = load_current_iceberg_base_table(state, left_ref)?;
    let right_loaded = load_current_iceberg_base_table(state, right_ref)?;
    let left_batch = plan_changes(&left_loaded.table, left_from, Some(left_to), &[])
        .map_err(|e| format!("join MV left change planning failed: {e}"))?;
    let right_batch = plan_changes(&right_loaded.table, right_from, Some(right_to), &[])
        .map_err(|e| format!("join MV right change planning failed: {e}"))?;
    if left_batch.current_snapshot_id != left_to {
        return Err(format!(
            "join MV left change batch snapshot mismatch: expected {left_to}, got {}",
            left_batch.current_snapshot_id
        )
        .into());
    }
    if right_batch.current_snapshot_id != right_to {
        return Err(format!(
            "join MV right change batch snapshot mismatch: expected {right_to}, got {}",
            right_batch.current_snapshot_id
        )
        .into());
    }
    let left_has_delete_changes = iceberg_change_batch_has_row_deletes(&left_batch);
    let right_has_delete_changes = iceberg_change_batch_has_row_deletes(&right_batch);
    let left_has_changes = !left_batch.inserts.is_empty() || left_has_delete_changes;
    let right_has_changes = !right_batch.inserts.is_empty() || right_has_delete_changes;
    let branches = crate::engine::mv::iceberg_join_branch::plan_join_delta_branches(
        left_ref,
        right_ref,
        crate::engine::mv::iceberg_join_branch::SnapshotWindow {
            from: left_from,
            to: left_to,
        },
        crate::engine::mv::iceberg_join_branch::SnapshotWindow {
            from: right_from,
            to: right_to,
        },
        left_has_changes,
        right_has_changes,
    );
    if branches.is_empty() {
        return Ok(
            finalize_iceberg_mv_metadata_only_refresh_with_partition_state(
                state,
                target,
                mv_definition,
                pin.to_snapshot_map(),
                pin.to_table_uuid_map(),
                IcebergMvPartitionStateFinalize::FromAffected(&ctx.affected_partitions),
            )?,
        );
    }
    let mode = if ctx.rewrite.schema_contract.aggregate.is_some() {
        JoinIncrementalRefreshMode::Coalesce
    } else {
        select_join_incremental_refresh_mode(left_has_delete_changes, right_has_delete_changes)
    };
    execute_join_delta_branches_logical(state, ctx, mode, branches)
}

fn column_ref_expr(column: &OutputColumn) -> TypedExpr {
    TypedExpr {
        kind: ExprKind::ColumnRef {
            column_id: column.column_id,
            qualifier: None,
            column: column.name.clone(),
        },
        data_type: column.data_type.clone(),
        nullable: column.nullable,
    }
}

fn execute_join_delta_branches_logical(
    state: &Arc<StandaloneState>,
    ctx: &IcebergMvRefreshContext,
    mode: JoinIncrementalRefreshMode,
    branches: Vec<crate::engine::mv::iceberg_join_branch::JoinDeltaBranchPlan>,
) -> Result<StatementResult, IcebergMvRefreshExecutionError> {
    if branches.is_empty() {
        return Err("join delta logical execution requires at least one branch"
            .to_string()
            .into());
    }
    let (plan, factory) = plan_canonical_select_for_imv(state, ctx).map_err(|err| err.message)?;
    let logical_input = JoinIncrementalLogicalInput { plan, factory };
    let logical_plan =
        build_join_incremental_refresh_logical_plan(&ctx.rewrite, mode, logical_input)?;
    let application_target = IcebergMvTarget::from(&ctx.rewrite.target);
    let target = &application_target;
    let target_entry = ctx.target_bindings.runtime().target_entry();
    let iceberg_catalog = &ctx.iceberg_catalog;
    let expected_main_snapshot_id = ctx.rewrite.target_snapshot_id;
    let mv_definition = &*ctx.rewrite.mv_definition;
    let connector_context = refresh_connector_context(ctx)?;
    let pin = &*ctx.rewrite.pin;
    let snapshots = pin.to_snapshot_map();
    let table_uuids = pin.to_table_uuid_map();
    let ident = iceberg_mv_table_ident(target)?;
    let staging_branch = format!(
        "__nova_mv_refresh_{}_{}",
        mv_definition.mv_id,
        uuid::Uuid::new_v4().simple()
    );
    let refresh_id = begin_staged_iceberg_mv_refresh_intent(
        state,
        target,
        mv_definition.mv_id,
        expected_main_snapshot_id,
        snapshots.clone(),
        &staging_branch,
    )?;
    let marker = match load_iceberg_mv_refresh_marker(state, refresh_id, mv_definition.mv_id) {
        Ok(refresh_marker) => build_mv_refresh_provenance(
            &refresh_marker,
            RefreshTechnique::Incremental,
            build_mv_refresh_provenance_bases(
                &snapshots,
                &table_uuids,
                &mv_definition.last_refresh_snapshots,
            ),
            mv_definition_fingerprint(&mv_definition.select_sql),
            // TODO(W3a): thread exact row count. The delta row counts
            // (`added_rows`/`deleted_rows`) are only known after the
            // change-stream write below, so the watermark is stamped now and
            // rows is left at 0.
            0,
        )
        .to_summary_properties()
        .map_err(|err| {
            handle_iceberg_mv_commit_error(
                state,
                target,
                target_entry,
                &staging_branch,
                refresh_id,
                err,
                connector_context,
            )
        })?,
        Err(err) => {
            return Err(handle_iceberg_mv_commit_error(
                state,
                target,
                target_entry,
                &staging_branch,
                refresh_id,
                err,
                connector_context,
            ));
        }
    };
    if let Err(err) = ensure_iceberg_mv_staging_branch(
        state,
        iceberg_catalog,
        target,
        &staging_branch,
        expected_main_snapshot_id,
        connector_context,
    ) {
        abort_iceberg_mv_refresh(state, refresh_id)?;
        return Err(err.into());
    }
    let target_table = match reload_iceberg_mv_target_table(target_entry, target) {
        Ok(table) => table,
        Err(err) => {
            return Err(handle_iceberg_mv_definite_pre_publish_error(
                state,
                target,
                target_entry,
                &staging_branch,
                refresh_id,
                err,
                connector_context,
            ));
        }
    };
    let target_backend = iceberg_mv_target_backend(target);
    let populated = execute_join_incremental_refresh_write(
        &target_table,
        &ident,
        &staging_branch,
        mode,
        logical_plan,
        |logical| {
            let connectors_snapshot = state
                .connectors
                .read()
                .expect("standalone connector registry read lock")
                .clone();
            let planned_query = crate::engine::plan_logical_for_iceberg_change_stream_refresh(
                logical.plan,
                logical.factory,
                &connectors_snapshot,
            )?;
            let producer_branches = match mode {
                JoinIncrementalRefreshMode::AppendOnly => {
                    vec![ImvChangeStreamProducerBranch::FreshData]
                }
                JoinIncrementalRefreshMode::Coalesce => vec![
                    ImvChangeStreamProducerBranch::DeleteDv,
                    ImvChangeStreamProducerBranch::ReuseData,
                    ImvChangeStreamProducerBranch::FreshData,
                ],
            };
            execute_imv_change_stream_writer(
                state,
                &target_backend,
                &target_table,
                ImvRefreshPlannedChangeStream {
                    optimized_tree: planned_query.optimized_tree,
                    output_columns: planned_query.output_columns,
                    change_stream: logical
                        .change_stream_override
                        .unwrap_or(planned_query.change_stream),
                    producer_branches,
                    mv_refresh_ctx: Some(ctx),
                },
                &staging_branch,
            )
        },
    )
    .map_err(|err| {
        handle_iceberg_mv_commit_error(
            state,
            target,
            target_entry,
            &staging_branch,
            refresh_id,
            err.into_message(),
            connector_context,
        )
    })?;

    let (added_rows, deleted_rows) = match populated.effect {
        crate::mv::refresh::change_stream_write::ChangeStreamWriteEffect::Empty => (0, 0),
        crate::mv::refresh::change_stream_write::ChangeStreamWriteEffect::Changed {
            added_rows,
            deleted_rows,
        } => (added_rows, deleted_rows),
    };
    let collector = populated.collector;
    let new_total_rows = match mode {
        JoinIncrementalRefreshMode::AppendOnly if added_rows == 0 =>
        {
            tracing::info!(
                snapshots = ?snapshots,
                "iceberg join mv {}.{}.{}: append-only logical refresh produced 0 effective rows; \
                 advancing lineage without new iceberg snapshot",
                target.catalog,
                target.namespace,
                target.table
            );
            drop_iceberg_mv_staging_branch(
                state,
                target,
                target_entry,
                &staging_branch,
                connector_context,
            )?;
            abort_iceberg_mv_refresh(state, refresh_id)?;
            let target_snapshot_id = recorded_target_snapshot_id(target, mv_definition)?;
            let metadata_refresh_id =
                begin_iceberg_mv_refresh_intent(state, mv_definition.mv_id, snapshots.clone())?;
            finalize_iceberg_mv_refresh_with_partition_state(
                state,
                metadata_refresh_id,
                mv_definition.last_refresh_rows.unwrap_or(0),
                snapshots,
                table_uuids,
                target_snapshot_id,
                IcebergMvPartitionStateFinalize::FromAffected(&ctx.affected_partitions),
            )
            .map_err(iceberg_mv_post_publish_finalize_error)?;
            return Ok(StatementResult::Ok);
        }
        JoinIncrementalRefreshMode::AppendOnly => mv_definition
            .last_refresh_rows
            .unwrap_or(0)
            .checked_add(added_rows)
            .ok_or_else(|| {
                handle_iceberg_mv_commit_error(
                    state,
                    target,
                    target_entry,
                    &staging_branch,
                    refresh_id,
                    format!(
                        "iceberg join MV append-only row-count overflow: current={:?}, inserts={added_rows}",
                        mv_definition.last_refresh_rows
                    ),
                    connector_context,
                )
            })?,
        JoinIncrementalRefreshMode::Coalesce if added_rows == 0 && deleted_rows == 0 =>
        {
            drop_iceberg_mv_staging_branch(
                state,
                target,
                target_entry,
                &staging_branch,
                connector_context,
            )?;
            abort_iceberg_mv_refresh(state, refresh_id)?;
            return Ok(
                finalize_iceberg_mv_metadata_only_refresh_with_partition_state(
                    state,
                    target,
                    mv_definition,
                    snapshots,
                    table_uuids,
                    IcebergMvPartitionStateFinalize::FromAffected(&ctx.affected_partitions),
                )?,
            );
        }
        JoinIncrementalRefreshMode::Coalesce => mv_definition
            .last_refresh_rows
            .unwrap_or(0)
            .checked_add(added_rows)
            .and_then(|rows| rows.checked_sub(deleted_rows))
            .ok_or_else(|| {
                handle_iceberg_mv_commit_error(
                    state,
                    target,
                    target_entry,
                    &staging_branch,
                    refresh_id,
                    format!(
                        "iceberg join MV row-count delta overflow: current={:?}, inserts={}, deletes={}",
                        mv_definition.last_refresh_rows, added_rows, deleted_rows
                    ),
                    connector_context,
                )
            })?,
    };

    let commit_outcome = match data_block_on(commit_iceberg_mv_with_populated_collector(
        &target_table,
        iceberg_catalog,
        target_entry,
        &ident,
        Arc::clone(&collector),
        &staging_branch,
        marker,
    )) {
        Ok(Ok(outcome)) => outcome,
        Ok(Err(err)) => {
            return Err(handle_iceberg_mv_commit_service_error(
                state,
                target,
                target_entry,
                &staging_branch,
                refresh_id,
                err,
                connector_context,
            ));
        }
        Err(err) => {
            return Err(handle_iceberg_mv_definite_pre_publish_error(
                state,
                target,
                target_entry,
                &staging_branch,
                refresh_id,
                err,
                connector_context,
            ));
        }
    };

    record_iceberg_mv_staging_commit(
        state,
        refresh_id,
        commit_outcome.new_snapshot_id,
        new_total_rows,
        table_uuids.clone(),
    )?;
    let published_snapshot_id = resolve_iceberg_mv_publication(
        state,
        target,
        target_entry,
        &staging_branch,
        refresh_id,
        None,
        connector_context,
        publish_iceberg_mv_refresh(
            state,
            target,
            target_entry,
            &staging_branch,
            expected_main_snapshot_id,
            commit_outcome.new_snapshot_id,
            refresh_id,
            mv_definition.mv_id,
            connector_context,
        ),
    )?;
    record_iceberg_mv_publish_commit(state, refresh_id, published_snapshot_id)?;
    drop_iceberg_mv_staging_branch(
        state,
        target,
        target_entry,
        &staging_branch,
        connector_context,
    )?;
    finalize_iceberg_mv_refresh_with_partition_state(
        state,
        refresh_id,
        new_total_rows,
        snapshots,
        table_uuids,
        published_snapshot_id,
        IcebergMvPartitionStateFinalize::FromAffected(&ctx.affected_partitions),
    )
    .map_err(iceberg_mv_post_publish_finalize_error)?;
    Ok(StatementResult::Ok)
}

#[cfg(test)]
fn should_use_join_delta_append_only_fast_path(
    query: &sqlparser::ast::Query,
    left_has_delete_changes: bool,
    right_has_delete_changes: bool,
) -> bool {
    !left_has_delete_changes
        && !right_has_delete_changes
        && crate::engine::mv::iceberg_join_branch::is_append_only_join_delta_eligible(query)
}

fn build_imv_refresh_catalog(
    state: &Arc<StandaloneState>,
    base_refs: &[&TableIdentity],
    pin: &RefreshSnapshotPin,
) -> Result<crate::sql::catalog::local::PlannerMemoryCatalog, String> {
    let mut catalog = crate::sql::catalog::local::PlannerMemoryCatalog::default();
    for base_ref in base_refs {
        let snapshot_id = pin
            .get(base_ref)
            .ok_or_else(|| format!("IMV refresh catalog missing pin for {}", base_ref.fqn()))?;
        let mut table_def =
            build_iceberg_table_def_for_snapshot_scan(state, base_ref, snapshot_id)?;
        table_def.name = base_ref.table.clone();
        catalog.create_database(&base_ref.namespace)?;
        catalog
            .register(&base_ref.namespace, table_def.clone())
            .map_err(|e| format!("register IMV refresh base table {}: {e}", base_ref.fqn()))?;
    }
    Ok(catalog)
}

fn build_join_delta_coalesce_catalog(
    state: &Arc<StandaloneState>,
    branches: &[crate::engine::mv::iceberg_join_branch::JoinDeltaBranchPlan],
    target: &IcebergMvTarget,
    target_table: &iceberg::table::Table,
    target_snapshot_id: Option<i64>,
) -> Result<crate::sql::catalog::local::PlannerMemoryCatalog, String> {
    let mut catalog = crate::sql::catalog::local::PlannerMemoryCatalog::default();
    let mut registered_delta_tables = BTreeSet::new();
    let mut registered_snapshot_tables = BTreeSet::new();
    for branch in branches {
        register_join_delta_coalesce_side(
            &mut catalog,
            state,
            &branch.left_base,
            branch.left,
            &mut registered_delta_tables,
            &mut registered_snapshot_tables,
        )?;
        register_join_delta_coalesce_side(
            &mut catalog,
            state,
            &branch.right_base,
            branch.right,
            &mut registered_delta_tables,
            &mut registered_snapshot_tables,
        )?;
    }
    register_join_delta_target_locator(
        &mut catalog,
        state,
        target,
        target_table,
        target_snapshot_id,
    )?;
    Ok(catalog)
}

fn register_join_delta_target_locator(
    catalog: &mut crate::sql::catalog::local::PlannerMemoryCatalog,
    state: &Arc<StandaloneState>,
    target: &IcebergMvTarget,
    target_table: &iceberg::table::Table,
    target_snapshot_id: Option<i64>,
) -> Result<(), String> {
    catalog.create_database(&target.namespace)?;
    let table_def =
        build_join_delta_target_locator_table_def(state, target, target_table, target_snapshot_id)?;
    catalog
        .register(&target.namespace, table_def)
        .map_err(|e| format!("register join coalesce target locator table: {e}"))
}

fn build_join_delta_target_locator_table_def(
    state: &Arc<StandaloneState>,
    target: &IcebergMvTarget,
    target_table: &iceberg::table::Table,
    target_snapshot_id: Option<i64>,
) -> Result<crate::sql::planner::table::TableDef, String> {
    let base = TableIdentity {
        catalog: target.catalog.clone(),
        namespace: target.namespace.clone(),
        table: target.table.clone(),
    };
    let mut table_def = match target_snapshot_id {
        Some(snapshot_id) => build_iceberg_table_def_for_snapshot_scan(state, &base, snapshot_id)?,
        None => build_empty_join_delta_target_locator_table_def(state, target)?,
    };
    table_def.name =
        crate::engine::mv::iceberg_join_branch::JOIN_DELTA_TARGET_LOCATOR_TABLE.to_string();
    expose_physical_apply_key_for_locator_registration(
        table_def,
        target_table,
        JOIN_APPLY_KEY_COLUMN_NAME,
    )
}

fn build_empty_join_delta_target_locator_table_def(
    state: &Arc<StandaloneState>,
    target: &IcebergMvTarget,
) -> Result<crate::sql::planner::table::TableDef, String> {
    let entry = {
        let registry = state
            .iceberg_catalogs
            .read()
            .map_err(|e| format!("iceberg catalog registry read lock: {e}"))?;
        registry.get(&target.catalog)?
    };
    let loaded =
        crate::connector::iceberg::catalog::load_table(&entry, &target.namespace, &target.table)?;
    let mut table_def = crate::connector::iceberg::catalog::build_iceberg_table_def_for_delta_scan(
        &target.catalog,
        &target.namespace,
        &target.table,
        loaded,
    )?;
    table_def
        .iceberg_row_lineage_metadata_columns
        .retain(|column| column.name != crate::exec::change_op::CHANGE_OP_COLUMN);
    Ok(table_def)
}

fn register_join_delta_coalesce_side(
    catalog: &mut crate::sql::catalog::local::PlannerMemoryCatalog,
    state: &Arc<StandaloneState>,
    base: &TableIdentity,
    side: crate::engine::mv::iceberg_join_branch::BranchSide,
    registered_delta_tables: &mut BTreeSet<String>,
    registered_snapshot_tables: &mut BTreeSet<String>,
) -> Result<(), String> {
    catalog.create_database(&base.namespace)?;
    let table_def = match side {
        crate::engine::mv::iceberg_join_branch::BranchSide::Delta(_) => {
            let key = join_catalog_registration_key(&base.catalog, &base.namespace, &base.table)?;
            if !registered_delta_tables.insert(key) {
                return Ok(());
            }
            crate::engine::query_prep::build_iceberg_table_def_for_delta_scan(
                state,
                &base.catalog,
                &base.namespace,
                &base.table,
            )?
        }
        crate::engine::mv::iceberg_join_branch::BranchSide::Snapshot(snapshot_id) => {
            let table_name = synthetic_snapshot_table_name(base, snapshot_id);
            let key = join_catalog_registration_key(&base.catalog, &base.namespace, &table_name)?;
            if !registered_snapshot_tables.insert(key) {
                return Ok(());
            }
            build_iceberg_table_def_for_snapshot_scan(state, base, snapshot_id)?
        }
    };
    catalog
        .register(&base.namespace, table_def)
        .map_err(|e| format!("register join coalesce table {}: {e}", base.fqn()))
}

fn join_catalog_registration_key(
    catalog: &str,
    namespace: &str,
    table: &str,
) -> Result<String, String> {
    Ok(format!(
        "{}.{}.{}",
        novarocks_catalog::identifier::normalize_identifier(catalog)?,
        novarocks_catalog::identifier::normalize_identifier(namespace)?,
        novarocks_catalog::identifier::normalize_identifier(table)?
    ))
}

fn normalize_join_branch_snapshot_tables(
    query: &mut sqlparser::ast::Query,
    branch: &crate::engine::mv::iceberg_join_branch::JoinDeltaBranchPlan,
) -> Result<(), String> {
    let sqlparser::ast::SetExpr::Select(select) = query.body.as_mut() else {
        return Err("join branch snapshot normalization requires SELECT body".to_string());
    };
    let [from] = select.from.as_mut_slice() else {
        return Err("join branch snapshot normalization requires one FROM item".to_string());
    };
    let [join] = from.joins.as_mut_slice() else {
        return Err("join branch snapshot normalization requires one JOIN".to_string());
    };
    if let crate::engine::mv::iceberg_join_branch::BranchSide::Snapshot(snapshot_id) = branch.left {
        rewrite_snapshot_table_factor(&mut from.relation, &branch.left_base, snapshot_id, None)?;
    }
    if let crate::engine::mv::iceberg_join_branch::BranchSide::Snapshot(snapshot_id) = branch.right
    {
        rewrite_snapshot_table_factor(&mut join.relation, &branch.right_base, snapshot_id, None)?;
    }
    Ok(())
}

/// Execute the incremental refresh of an iceberg-backed MV.
///
/// IVM-A1 path: plan the MV change stream, execute it through the distributed
/// Iceberg change-stream write DAG, and route writer reports into a shared
/// `IcebergCommitCollector`. After the pipeline completes, the refresh driver
/// hands the populated collector to
/// `commit_iceberg_mv_with_populated_collector` for the staging-branch commit,
/// then publishes and finalizes.
///
/// Steps:
/// 1. Plan the change batch from `previous_snapshot_id` to `current_snapshot_id`
///    (also used to short-circuit empty-delta finalize).
/// 2. If the delta yields no inserts and no deletes, advance lineage without
///    committing an empty Iceberg snapshot.
/// 3. Otherwise: begin staging branch, build the collector, run the distributed
///    change-stream write DAG, commit, publish, and finalize.
///
/// Metadata-only empty deltas keep the old finalize path because no Iceberg
/// snapshot is created.
#[derive(Clone, Copy)]
struct RewriteMergeRefreshOptions {
    apply_key: ApplyKeyContract,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum RewriteMergeRefreshEvidence {
    None,
    Aggregate,
    JoinAggregate,
    BranchUnionAggregate,
}

fn rewrite_merge_refresh_evidence(apply_key: ApplyKeyContract) -> RewriteMergeRefreshEvidence {
    match (apply_key.rewrite_evidence, apply_key.value_type) {
        (RewriteEvidence::None, _) => RewriteMergeRefreshEvidence::None,
        (
            RewriteEvidence::Aggregate,
            crate::mv::refresh::apply_key::ApplyKeyValueType::BranchUtf8,
        ) => RewriteMergeRefreshEvidence::BranchUnionAggregate,
        (RewriteEvidence::Aggregate, _) => RewriteMergeRefreshEvidence::Aggregate,
        (RewriteEvidence::JoinAggregate, _) => RewriteMergeRefreshEvidence::JoinAggregate,
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ImvChangeStreamProducerBranch {
    DeleteDv,
    ReuseData,
    FreshData,
}

const IMV_CHANGE_STREAM_DATA_ROUTE_COLUMN: &str = "__change_data_route";

struct ImvRefreshPlannedChangeStream<'a> {
    optimized_tree: crate::sql::optimizer::OptimizedOperatorNode,
    output_columns: Vec<OutputColumn>,
    change_stream: crate::sql::planner::imv_rewrite::change_stream::ImvChangeStreamDescriptor,
    producer_branches: Vec<ImvChangeStreamProducerBranch>,
    mv_refresh_ctx: Option<&'a IcebergMvRefreshContext>,
}

#[cfg(test)]
std::thread_local! {
    static IMV_CHANGE_STREAM_EXECUTION_RESULT_FOR_TEST: std::cell::RefCell<
        Option<crate::query_execution::outcome::QueryExecutionResult>,
    > = const { std::cell::RefCell::new(None) };
}

#[cfg(test)]
struct ImvChangeStreamExecutionResultGuard {
    _not_send: std::marker::PhantomData<std::rc::Rc<()>>,
}

#[cfg(test)]
impl Drop for ImvChangeStreamExecutionResultGuard {
    fn drop(&mut self) {
        IMV_CHANGE_STREAM_EXECUTION_RESULT_FOR_TEST.with(|slot| {
            *slot.borrow_mut() = None;
        });
    }
}

#[cfg(test)]
fn install_imv_change_stream_execution_result_for_test(
    result: crate::query_execution::outcome::QueryExecutionResult,
) -> ImvChangeStreamExecutionResultGuard {
    IMV_CHANGE_STREAM_EXECUTION_RESULT_FOR_TEST.with(|slot| {
        let replaced = slot.borrow_mut().replace(result);
        assert!(
            replaced.is_none(),
            "IMV change-stream execution result already installed for this test thread"
        );
    });
    ImvChangeStreamExecutionResultGuard {
        _not_send: std::marker::PhantomData,
    }
}

#[cfg(test)]
fn take_imv_change_stream_execution_result_for_test()
-> Option<crate::query_execution::outcome::QueryExecutionResult> {
    IMV_CHANGE_STREAM_EXECUTION_RESULT_FOR_TEST.with(|slot| slot.borrow_mut().take())
}

#[cfg(test)]
fn imv_change_stream_writer_abort_result_for_test(
    reason: &str,
) -> crate::query_execution::outcome::QueryExecutionResult {
    let mut abort =
        crate::engine::write_operation_lifecycle::test_support::write_abort_with_data_file();
    abort.reason = reason.to_string();
    crate::query_execution::outcome::QueryExecutionResult {
        query_result: crate::runtime::query_result::QueryResult::empty(),
        write_commit: None,
        write_abort: Some(abort),
        fragment_profiles: Vec::new(),
    }
}

#[allow(clippy::too_many_arguments)]
fn execute_imv_change_stream_write(
    state: &Arc<StandaloneState>,
    target: &crate::engine::backend_resolver::TargetBackend,
    table: iceberg::table::Table,
    ident: &TableIdent,
    op_kind: CommitOpKind,
    refresh_plan: ImvRefreshPlannedChangeStream<'_>,
    target_ref: &str,
) -> Result<
    crate::mv::refresh::change_stream_write::PopulatedChangeStreamWrite,
    crate::mv::refresh::change_stream_write::ChangeStreamWriteError,
> {
    crate::mv::refresh::change_stream_write::execute_and_collect_change_stream_write(
        &table,
        ident,
        target_ref,
        op_kind,
        || execute_imv_change_stream_writer(state, target, &table, refresh_plan, target_ref),
    )
}

fn execute_imv_change_stream_writer(
    state: &Arc<StandaloneState>,
    target: &crate::engine::backend_resolver::TargetBackend,
    table: &iceberg::table::Table,
    refresh_plan: ImvRefreshPlannedChangeStream<'_>,
    target_ref: &str,
) -> Result<crate::mv::refresh::change_stream_write::ExecutedChangeStreamWrite, String> {
    let (refresh_plan, data_route_output_ordinal) =
        ensure_imv_change_stream_data_route(refresh_plan)?;
    let entry = state
        .iceberg_catalogs
        .read()
        .map_err(|e| format!("iceberg catalog registry read lock: {e}"))?
        .get(&target.catalog)?;
    let connector_context = refresh_plan
        .mv_refresh_ctx
        .and_then(|ctx| ctx.connector_context.as_ref())
        .ok_or_else(|| {
            "Iceberg MV change-stream write is missing its caller connector context".to_string()
        })?;
    crate::connector::validate_request_context(connector_context)?;
    let resolved = crate::connector::metadata_load_table(
        state.connector_control.as_ref(),
        connector_context.clone(),
        &target.catalog,
        &target.namespace,
        &target.table,
        novarocks_spi::connector::ConnectorTableResolution::StrictBaseTable,
    )?
    .0;
    let mut dag = iceberg_change_stream_write_dag_for_imv_refresh(
        target,
        &resolved,
        table,
        &entry,
        &refresh_plan,
        target_ref,
        data_route_output_ordinal,
    )?;
    let planned =
        crate::engine::build_physical_plan_as_iceberg_change_stream_write_with_connector_context(
            state,
            Some(&target.catalog),
            &target.namespace,
            &refresh_plan.optimized_tree,
            &mut dag,
            refresh_plan.mv_refresh_ctx,
            None,
            connector_context,
        )?;
    #[cfg(test)]
    if let Some(result) = take_imv_change_stream_execution_result_for_test() {
        return executed_change_stream_write_from_result(result, planned.commit_plan);
    }
    #[cfg(test)]
    if let Some(result) =
        crate::engine::observe_change_stream_write_build_for_test(&planned.topology)
    {
        return executed_change_stream_write_from_result(result, planned.commit_plan);
    }
    let result = crate::engine::execute_planned_iceberg_change_stream_write(
        state,
        planned.prepared,
        planned.native_bundle,
        None,
        None,
    )?;
    executed_change_stream_write_from_result(result, planned.commit_plan)
}

fn executed_change_stream_write_from_result(
    result: crate::query_execution::outcome::QueryExecutionResult,
    commit_plan: crate::connector::iceberg::change_stream_routing::ChangeStreamWriterCommitPlan,
) -> Result<crate::mv::refresh::change_stream_write::ExecutedChangeStreamWrite, String> {
    if let Some(abort) = result.write_abort {
        return Err(abort.reason);
    }
    let write_commit = result
        .write_commit
        .ok_or_else(|| "IMV change-stream write completed without writer commit".to_string())?;
    Ok(
        crate::mv::refresh::change_stream_write::ExecutedChangeStreamWrite {
            write_commit,
            commit_plan,
        },
    )
}

fn ensure_imv_change_stream_data_route(
    mut refresh_plan: ImvRefreshPlannedChangeStream<'_>,
) -> Result<(ImvRefreshPlannedChangeStream<'_>, Option<usize>), String> {
    let Some(route_mode) = imv_data_route_mode(&refresh_plan.producer_branches)? else {
        return Ok((refresh_plan, None));
    };

    let has_delete_branch = refresh_plan
        .producer_branches
        .iter()
        .any(|branch| matches!(branch, ImvChangeStreamProducerBranch::DeleteDv));
    let action_output = if has_delete_branch {
        let action_ordinal = imv_change_op_output_ordinal(&refresh_plan)?;
        Some(refresh_plan.output_columns[action_ordinal].clone())
    } else {
        None
    };
    let row_lineage_output = match route_mode {
        ImvDataRouteMode::Constant(_) => None,
        ImvDataRouteMode::ByRowLineage => Some(
            output_column_by_name(
                &refresh_plan.output_columns,
                crate::exec::row_position::ICEBERG_ROW_ID_COL,
                "reuse/fresh route row-lineage column",
            )?
            .clone(),
        ),
    };

    let route_output = imv_data_route_output_column(&refresh_plan.output_columns);
    let route_output_ordinal = refresh_plan.output_columns.len();
    let optimized_tree = add_imv_data_route_project(
        refresh_plan.optimized_tree,
        &refresh_plan.output_columns,
        action_output.as_ref(),
        row_lineage_output.as_ref(),
        route_mode,
        route_output.clone(),
    )?;
    refresh_plan.optimized_tree = optimized_tree;
    refresh_plan.output_columns.push(route_output);

    Ok((refresh_plan, Some(route_output_ordinal)))
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ImvDataRouteMode {
    Constant(i32),
    ByRowLineage,
}

fn imv_data_route_mode(
    producer_branches: &[ImvChangeStreamProducerBranch],
) -> Result<Option<ImvDataRouteMode>, String> {
    use crate::sql::common::{DATA_ROUTE_FRESH, DATA_ROUTE_REUSE};

    let has_reuse = producer_branches
        .iter()
        .any(|branch| matches!(branch, ImvChangeStreamProducerBranch::ReuseData));
    let has_fresh = producer_branches
        .iter()
        .any(|branch| matches!(branch, ImvChangeStreamProducerBranch::FreshData));
    Ok(match (has_reuse, has_fresh) {
        (false, false) => None,
        (true, false) => Some(ImvDataRouteMode::Constant(DATA_ROUTE_REUSE)),
        (false, true) => Some(ImvDataRouteMode::Constant(DATA_ROUTE_FRESH)),
        (true, true) => Some(ImvDataRouteMode::ByRowLineage),
    })
}

fn imv_data_route_output_column(existing: &[OutputColumn]) -> OutputColumn {
    OutputColumn {
        column_id: ColumnId(
            existing
                .iter()
                .map(|column| column.column_id.0)
                .max()
                .unwrap_or(0)
                + 1,
        ),
        name: IMV_CHANGE_STREAM_DATA_ROUTE_COLUMN.to_string(),
        data_type: DataType::Int32,
        nullable: true,
        is_internal: true,
    }
}

fn add_imv_data_route_project(
    child: crate::sql::optimizer::OptimizedOperatorNode,
    child_output_columns: &[OutputColumn],
    action_output: Option<&OutputColumn>,
    row_lineage_output: Option<&OutputColumn>,
    route_mode: ImvDataRouteMode,
    route_output: OutputColumn,
) -> Result<crate::sql::optimizer::OptimizedOperatorNode, String> {
    use crate::sql::optimizer::operator::{Operator, ProjectOp, ScalarProjectItem};
    use crate::sql::optimizer::optimized_tree::{PlanExecutionProps, attach_scalar_arena};
    use crate::sql::optimizer::scalar::ScalarNode;

    let existing_arena =
        child.execution_props.scalar_arena.as_ref().ok_or_else(|| {
            "IMV change-stream route projection requires a scalar arena".to_string()
        })?;
    let mut arena = (**existing_arena).clone();
    let mut items = Vec::with_capacity(child_output_columns.len() + 1);
    for column in child_output_columns {
        arena.remember_source_column_display(column.column_id, None, column.name.clone());
        let expr = arena.intern(
            ScalarNode::ColumnRef(column.column_id),
            column.data_type.clone(),
            column.nullable,
        );
        items.push(ScalarProjectItem {
            expr,
            output_name: column.name.clone(),
            output_column_id: column.column_id,
            expr_display: None,
        });
    }

    let route_expr =
        imv_data_route_scalar(&mut arena, action_output, row_lineage_output, route_mode)?;
    arena.remember_project_output_display(route_output.column_id, None, route_output.name.clone());
    items.push(ScalarProjectItem {
        expr: route_expr,
        output_name: route_output.name.clone(),
        output_column_id: route_output.column_id,
        expr_display: None,
    });

    let output_property = child.execution_props.output_property.clone();
    let stats = child.stats.clone();
    let mut output_columns = child_output_columns.to_vec();
    output_columns.push(route_output);
    let arena = Arc::new(arena);
    let mut plan = crate::sql::optimizer::OptimizedOperatorNode {
        op: Operator::PhysicalProject(ProjectOp {
            items,
            output_qualifier: None,
        }),
        children: vec![child],
        stats,
        explain_stats: crate::sql::optimizer::optimized_tree::OptimizerExplainStats::default(),
        output_columns,
        execution_props: PlanExecutionProps {
            output_property: output_property.clone(),
            child_output_properties: vec![output_property],
            join_distribution: None,
            scalar_arena: Some(Arc::clone(&arena)),
        },
    };
    attach_scalar_arena(&mut plan, arena);
    Ok(plan)
}

fn imv_data_route_scalar(
    arena: &mut crate::sql::optimizer::scalar::ScalarArena,
    action_output: Option<&OutputColumn>,
    row_lineage_output: Option<&OutputColumn>,
    route_mode: ImvDataRouteMode,
) -> Result<crate::sql::optimizer::scalar::ScalarId, String> {
    use crate::sql::common::{
        BinOp, CHANGE_OP_INSERT, DATA_ROUTE_FRESH, DATA_ROUTE_REUSE, LiteralValue,
    };
    use crate::sql::optimizer::scalar::{HashableLiteral, ScalarNode};

    let route_value_expr = match route_mode {
        ImvDataRouteMode::Constant(route_value) => arena.intern(
            ScalarNode::Literal(HashableLiteral(LiteralValue::Int(route_value as i64))),
            DataType::Int32,
            false,
        ),
        ImvDataRouteMode::ByRowLineage => {
            let row_lineage_output = row_lineage_output.ok_or_else(|| {
                "IMV reuse/fresh route requires preserved row-lineage output".to_string()
            })?;
            let row_lineage_ref = arena.intern(
                ScalarNode::ColumnRef(row_lineage_output.column_id),
                row_lineage_output.data_type.clone(),
                row_lineage_output.nullable,
            );
            let is_fresh = arena.intern(
                ScalarNode::IsNull {
                    child: row_lineage_ref,
                    negated: false,
                },
                DataType::Boolean,
                false,
            );
            let fresh_route = arena.intern(
                ScalarNode::Literal(HashableLiteral(LiteralValue::Int(DATA_ROUTE_FRESH as i64))),
                DataType::Int32,
                false,
            );
            let reuse_route = arena.intern(
                ScalarNode::Literal(HashableLiteral(LiteralValue::Int(DATA_ROUTE_REUSE as i64))),
                DataType::Int32,
                false,
            );
            arena.intern(
                ScalarNode::Case {
                    operand: None,
                    when_then: vec![(is_fresh, fresh_route)],
                    else_expr: Some(reuse_route),
                },
                DataType::Int32,
                false,
            )
        }
    };
    let Some(action_output) = action_output else {
        return Ok(route_value_expr);
    };

    let action_ref = arena.intern(
        ScalarNode::ColumnRef(action_output.column_id),
        action_output.data_type.clone(),
        action_output.nullable,
    );
    let insert_literal = arena.intern(
        ScalarNode::Literal(HashableLiteral(LiteralValue::Int(CHANGE_OP_INSERT as i64))),
        action_output.data_type.clone(),
        false,
    );
    let is_insert = arena.intern(
        ScalarNode::BinaryOp {
            op: BinOp::Eq,
            left: action_ref,
            right: insert_literal,
        },
        DataType::Boolean,
        action_output.nullable,
    );
    let null_route = arena.intern(
        ScalarNode::Literal(HashableLiteral(LiteralValue::Null)),
        DataType::Int32,
        true,
    );
    Ok(arena.intern(
        ScalarNode::Case {
            operand: None,
            when_then: vec![(is_insert, route_value_expr)],
            else_expr: Some(null_route),
        },
        DataType::Int32,
        true,
    ))
}

fn iceberg_mv_target_backend(
    target: &IcebergMvTarget,
) -> crate::engine::backend_resolver::TargetBackend {
    crate::engine::backend_resolver::TargetBackend {
        backend_name: "iceberg",
        catalog: target.catalog.clone(),
        namespace: target.namespace.clone(),
        table: target.table.clone(),
    }
}

fn iceberg_change_stream_write_dag_for_imv_refresh(
    target: &crate::engine::backend_resolver::TargetBackend,
    resolved: &crate::connector::backend::ResolvedTable,
    table: &iceberg::table::Table,
    entry: &crate::connector::iceberg::catalog::IcebergCatalogEntry,
    refresh_plan: &ImvRefreshPlannedChangeStream<'_>,
    target_ref: &str,
    data_route_output_ordinal: Option<usize>,
) -> Result<crate::sql::planner::distributed::write::change_stream::ChangeStreamWriteDagSpec, String>
{
    let branches = build_imv_change_stream_branches(
        target,
        resolved,
        table,
        entry,
        &refresh_plan.output_columns,
        &refresh_plan.producer_branches,
        target_ref,
    )?;
    Ok(
        crate::sql::planner::distributed::write::change_stream::ChangeStreamWriteDagSpec {
            change_op_output_ordinal: Some(imv_change_op_output_ordinal(refresh_plan)?),
            data_route_output_ordinal,
            branches,
        },
    )
}

fn imv_change_op_output_ordinal(
    refresh_plan: &ImvRefreshPlannedChangeStream<'_>,
) -> Result<usize, String> {
    if let Some(aggregate) = refresh_plan.change_stream.aggregate() {
        return output_ordinal_by_column_id(
            &refresh_plan.output_columns,
            aggregate.action_column_id,
            "aggregate change-stream action column",
        );
    }
    if let Some(join_refresh) = refresh_plan.change_stream.join_refresh.as_ref() {
        return output_ordinal_by_column_id(
            &refresh_plan.output_columns,
            join_refresh.action_column.column_id,
            "join change-stream action column",
        );
    }
    refresh_plan
        .output_columns
        .iter()
        .position(is_imv_change_op_output_column)
        .ok_or_else(|| {
            let outputs = refresh_plan
                .output_columns
                .iter()
                .enumerate()
                .map(|(idx, column)| {
                    format!(
                        "#{idx}:{}:{:?}:internal={}",
                        column.name, column.column_id, column.is_internal
                    )
                })
                .collect::<Vec<_>>()
                .join(", ");
            format!(
                "IMV change-stream write requires __change_op output column; outputs=[{outputs}]"
            )
        })
}

fn is_imv_change_op_output_column(column: &OutputColumn) -> bool {
    column
        .name
        .eq_ignore_ascii_case(crate::exec::change_op::CHANGE_OP_COLUMN)
        && column.data_type == DataType::Int8
        && !column.nullable
}

fn build_imv_change_stream_branches(
    target: &crate::engine::backend_resolver::TargetBackend,
    resolved: &crate::connector::backend::ResolvedTable,
    table: &iceberg::table::Table,
    entry: &crate::connector::iceberg::catalog::IcebergCatalogEntry,
    output_columns: &[OutputColumn],
    producer_branches: &[ImvChangeStreamProducerBranch],
    target_ref: &str,
) -> Result<
    Vec<crate::sql::planner::distributed::write::change_stream::ChangeStreamWriteBranchSpec>,
    String,
> {
    use crate::sql::common::ChangeStreamBranchKind;
    use crate::sql::planner::distributed::write::change_stream::ChangeStreamWriteBranchSpec;
    use crate::sql::planner::distributed::write::sink::IcebergWriteSinkMode;

    producer_branches
        .iter()
        .copied()
        .enumerate()
        .map(|(idx, producer_branch)| {
            let branch_kind = match producer_branch {
                ImvChangeStreamProducerBranch::DeleteDv => ChangeStreamBranchKind::DeleteDv,
                ImvChangeStreamProducerBranch::ReuseData => ChangeStreamBranchKind::ReuseData,
                ImvChangeStreamProducerBranch::FreshData => ChangeStreamBranchKind::FreshData,
            };
            let (sink_spec, partition_ordinals) = match producer_branch {
                ImvChangeStreamProducerBranch::DeleteDv => {
                    let planned_snapshot_id = if target_ref == "main" {
                        table.metadata().current_snapshot().map(|s| s.snapshot_id())
                    } else {
                        crate::connector::iceberg::ref_snapshot::resolve_branch_head_snapshot_id(
                            table.metadata(),
                            target_ref,
                        )?
                    };
                    let mut spec = crate::engine::iceberg_writer::build_position_delete_sink_spec(
                        target, resolved, table, entry,
                    )?;
                    spec.mode = IcebergWriteSinkMode::DeletionVectors;
                    spec.set_planned_snapshot_id(planned_snapshot_id)?;
                    let file_ordinal = output_ordinal_by_name(
                        output_columns,
                        crate::exec::row_position::ICEBERG_FILE_PATH_COL,
                        "DV file locator",
                    )?;
                    (spec, vec![file_ordinal])
                }
                ImvChangeStreamProducerBranch::ReuseData => {
                    let spec = crate::engine::iceberg_writer::build_row_lineage_data_sink_spec(
                        target, resolved, table, entry,
                    )?;
                    let partition_ordinals =
                        target_partition_source_ordinals(table.metadata(), output_columns)?;
                    (spec, partition_ordinals)
                }
                ImvChangeStreamProducerBranch::FreshData => {
                    let write_columns =
                        crate::engine::iceberg_writer::iceberg_insert_columns_from_schema(
                            table.metadata().current_schema(),
                        )?;
                    let spec = crate::engine::iceberg_writer::build_insert_write_sink_spec(
                        target,
                        resolved,
                        table,
                        entry,
                        &write_columns,
                    )?;
                    let partition_ordinals =
                        target_partition_source_ordinals(table.metadata(), output_columns)?;
                    (spec, partition_ordinals)
                }
            };
            let stream_output_ordinals =
                output_ordinals_for_sink_columns(output_columns, &sink_spec.target_columns)?;
            Ok(ChangeStreamWriteBranchSpec {
                branch_id: i32::try_from(idx).map_err(|_| {
                    "IMV change-stream branch id overflow while building DAG".to_string()
                })?,
                branch_kind,
                stream_output_ordinals,
                output_partition_ordinals: partition_ordinals,
                sink_spec,
            })
        })
        .collect()
}

fn output_ordinals_for_sink_columns(
    output_columns: &[OutputColumn],
    sink_columns: &[novarocks_catalog::schema::ColumnDef],
) -> Result<Vec<usize>, String> {
    sink_columns
        .iter()
        .map(|column| output_ordinal_by_name(output_columns, &column.name, "sink input column"))
        .collect()
}

fn output_column_by_name<'a>(
    output_columns: &'a [OutputColumn],
    name: &str,
    label: &str,
) -> Result<&'a OutputColumn, String> {
    let ordinal = output_ordinal_by_name(output_columns, name, label)?;
    Ok(&output_columns[ordinal])
}

fn target_partition_source_ordinals(
    metadata: &iceberg::spec::TableMetadata,
    output_columns: &[OutputColumn],
) -> Result<Vec<usize>, String> {
    let schema = metadata.current_schema();
    metadata
        .default_partition_spec()
        .fields()
        .iter()
        .map(|field| {
            let source = schema.field_by_id(field.source_id).ok_or_else(|| {
                format!(
                    "IMV change-stream partition source field id {} not found in target schema",
                    field.source_id
                )
            })?;
            output_ordinal_by_name(
                output_columns,
                &source.name,
                "target partition source column",
            )
        })
        .collect()
}

fn output_ordinal_by_column_id(
    output_columns: &[OutputColumn],
    column_id: ColumnId,
    label: &str,
) -> Result<usize, String> {
    let mut matches = output_columns
        .iter()
        .enumerate()
        .filter(|(_, column)| column.column_id == column_id)
        .map(|(idx, _)| idx);
    let ordinal = matches.next().ok_or_else(|| {
        format!(
            "IMV change-stream {label} ColumnId({}) not found",
            column_id.0
        )
    })?;
    if matches.next().is_some() {
        return Err(format!(
            "IMV change-stream {label} ColumnId({}) is ambiguous",
            column_id.0
        ));
    }
    Ok(ordinal)
}

fn output_ordinal_by_name(
    output_columns: &[OutputColumn],
    name: &str,
    label: &str,
) -> Result<usize, String> {
    let mut matches = output_columns
        .iter()
        .enumerate()
        .filter(|(_, column)| column.name.eq_ignore_ascii_case(name))
        .map(|(idx, _)| idx);
    let ordinal = matches
        .next()
        .ok_or_else(|| format!("IMV change-stream {label} `{name}` not found in plan output"))?;
    if matches.next().is_some() {
        return Err(format!(
            "IMV change-stream {label} `{name}` is ambiguous in plan output"
        ));
    }
    Ok(ordinal)
}

#[cfg(test)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ImvBranchShape {
    DeleteAndReuse,
}

#[cfg(test)]
fn build_imv_change_stream_branches_for_test(
    shape: ImvBranchShape,
) -> Vec<crate::sql::planner::distributed::write::change_stream::ChangeStreamWriteBranchSpec> {
    use crate::sql::common::ChangeStreamBranchKind;
    use crate::sql::planner::distributed::write::change_stream::ChangeStreamWriteBranchSpec;
    match shape {
        ImvBranchShape::DeleteAndReuse => vec![
            ChangeStreamWriteBranchSpec::for_test(0, ChangeStreamBranchKind::DeleteDv, Vec::new()),
            ChangeStreamWriteBranchSpec::for_test(1, ChangeStreamBranchKind::ReuseData, Vec::new()),
        ],
    }
}

#[derive(Clone, Copy)]
enum FullRebuildSelectPreparation<'a> {
    Projection {
        select_sql: &'a str,
        pin: &'a RefreshSnapshotPin,
        current_catalog: Option<&'a str>,
        current_database: &'a str,
    },
    LegacyVisible {
        select_sql: &'a str,
    },
}

#[allow(clippy::too_many_arguments)]
fn incremental_refresh_iceberg_mv(
    state: &Arc<StandaloneState>,
    ctx: &IcebergMvRefreshContext,
    base_ref: &TableIdentity,
    previous_snapshot_id: i64,
    current_snapshot_id: i64,
    base_table: &iceberg::table::Table,
    current_table_uuid: &str,
    full_rebuild_select: FullRebuildSelectPreparation<'_>,
    options: RewriteMergeRefreshOptions,
) -> Result<StatementResult, IcebergMvRefreshExecutionError> {
    let change = NonJoinBaseChange {
        base_ref,
        previous_snapshot_id,
        current_snapshot_id,
        base_table,
        current_table_uuid,
    };
    incremental_refresh_iceberg_mv_with_changes(
        state,
        ctx,
        &[change],
        Some(full_rebuild_select),
        options,
    )
}

fn validate_non_join_change_plan_before_intent(
    plan: NonJoinIncrementalChangePlan,
    change_count: usize,
    allow_full_rebuild: bool,
    has_pinned_full_select: bool,
    target: &IcebergMvTarget,
) -> Result<NonJoinIncrementalChangePlan, String> {
    let NonJoinIncrementalChangePlan::FullRebuild { reason, .. } = &plan else {
        return Ok(plan);
    };
    if !allow_full_rebuild {
        return Err(format!(
            "iceberg aggregate MV {}.{}.{} cannot refresh incrementally and automatic full rebuild is disabled: {reason}",
            target.catalog, target.namespace, target.table
        ));
    }
    if change_count != 1 {
        return Err(format!(
            "iceberg MV {}.{}.{} cannot fall back to full rebuild for multi-base incremental refresh: {reason}",
            target.catalog, target.namespace, target.table
        ));
    }
    if !has_pinned_full_select {
        return Err(format!(
            "iceberg MV {}.{}.{} full rebuild fallback requires pinned full SELECT",
            target.catalog, target.namespace, target.table
        ));
    }
    Ok(plan)
}

#[allow(clippy::too_many_arguments)]
fn incremental_refresh_iceberg_mv_with_changes(
    state: &Arc<StandaloneState>,
    ctx: &IcebergMvRefreshContext,
    changes: &[NonJoinBaseChange<'_>],
    full_rebuild_select: Option<FullRebuildSelectPreparation<'_>>,
    options: RewriteMergeRefreshOptions,
) -> Result<StatementResult, IcebergMvRefreshExecutionError> {
    let application_target = IcebergMvTarget::from(&ctx.rewrite.target);
    let target = &application_target;
    let target_entry = ctx.target_bindings.runtime().target_entry();
    let iceberg_catalog = &ctx.iceberg_catalog;
    let expected_main_snapshot_id = ctx.rewrite.target_snapshot_id;
    let current_database = ctx.rewrite.current_database.as_str();
    let mv_definition = &*ctx.rewrite.mv_definition;
    let connector_context = refresh_connector_context(ctx)?;
    let apply_key = options.apply_key;
    let rewrite_evidence = rewrite_merge_refresh_evidence(apply_key);
    // 1. Canonical change planning runs before any refresh intent or staging
    // branch is created. Engine consumes the typed plan and owns lifecycle policy.
    let change_plan = validate_non_join_change_plan_before_intent(
        plan_non_join_incremental_changes(changes)?,
        changes.len(),
        apply_key.allow_full_rebuild_on_policy_full_refresh,
        full_rebuild_select.is_some(),
        target,
    )?;
    let (lineage, has_delete_changes) = match change_plan {
        NonJoinIncrementalChangePlan::MetadataOnly(lineage) => {
            let snapshots = &lineage.snapshots;
            let table_uuids = &lineage.table_uuids;
            // 2. Empty delta: advance lineage without committing a data-carrying
            // Iceberg snapshot. This must run before any staging-branch work.
            tracing::info!(
                snapshots = ?snapshots,
                "iceberg mv {}.{}.{}: incremental refresh delta has 0 rows; \
                 advancing lineage without new iceberg snapshot",
                target.catalog,
                target.namespace,
                target.table
            );
            let refresh_id =
                begin_iceberg_mv_refresh_intent(state, mv_definition.mv_id, snapshots.clone())?;
            // W4/M6: the base watermark advanced but the delta is empty, so no data
            // snapshot is committed. Advance the lake watermark with a data-free
            // snapshot so the storage table's current-snapshot provenance keeps up
            // with the SQLite watermark; use its id as the recorded target snapshot
            // when committed.
            let target_snapshot_id = advance_lake_watermark_via_data_free_snapshot(
                target,
                target_entry,
                iceberg_catalog,
                mv_definition,
                refresh_id,
                snapshots,
                table_uuids,
            )?
            .map(Ok)
            .unwrap_or_else(|| recorded_target_snapshot_id(target, mv_definition))?;
            finalize_iceberg_mv_refresh_with_partition_state(
                state,
                refresh_id,
                mv_definition.last_refresh_rows.unwrap_or(0),
                snapshots.clone(),
                table_uuids.clone(),
                target_snapshot_id,
                IcebergMvPartitionStateFinalize::FromAffected(&ctx.affected_partitions),
            )
            .map_err(iceberg_mv_post_publish_finalize_error)?;
            return Ok(StatementResult::Ok);
        }
        NonJoinIncrementalChangePlan::FullRebuild { lineage, reason } => {
            let [change] = changes else {
                return Err(
                    "iceberg MV full rebuild plan violated the validated single-base contract"
                        .to_string()
                        .into(),
                );
            };
            let full_rebuild_select = full_rebuild_select.ok_or_else(|| {
                "iceberg MV full rebuild plan lost its validated pinned full SELECT".to_string()
            })?;
            let physical_full_select_sql = match full_rebuild_select {
                FullRebuildSelectPreparation::Projection {
                    select_sql,
                    pin,
                    current_catalog,
                    current_database,
                } => prepare_projection_full_read_sql(
                    select_sql,
                    pin,
                    current_catalog,
                    current_database,
                )?,
                FullRebuildSelectPreparation::LegacyVisible { select_sql } => {
                    iceberg_mv_physical_select_sql(select_sql)?
                }
            };
            tracing::info!(
                "iceberg mv {}.{}.{}: incremental planner requested full refresh: {reason}",
                target.catalog,
                target.namespace,
                target.table
            );
            let staging_branch = format!(
                "__nova_mv_refresh_{}_{}",
                mv_definition.mv_id,
                uuid::Uuid::new_v4().simple()
            );
            let refresh_id = begin_staged_iceberg_mv_refresh_intent(
                state,
                target,
                mv_definition.mv_id,
                expected_main_snapshot_id,
                lineage.snapshots,
                &staging_branch,
            )?;
            return rebuild_iceberg_mv(
                state,
                target,
                target_entry,
                iceberg_catalog,
                expected_main_snapshot_id,
                &staging_branch,
                refresh_id,
                current_database,
                mv_definition,
                &physical_full_select_sql,
                change.base_ref,
                Some(change.current_snapshot_id),
                change.current_table_uuid,
                None,
                ctx.connector_context.as_ref().ok_or_else(|| {
                    "Iceberg MV refresh is missing its caller connector context".to_string()
                })?,
            );
        }
        NonJoinIncrementalChangePlan::ChangeStream {
            lineage,
            has_delete_changes,
        } => (lineage, has_delete_changes),
    };
    let snapshots = lineage.snapshots;
    let table_uuids = lineage.table_uuids;

    // 3. Begin the staging branch and pre-load the target Iceberg table.
    let staging_branch = format!(
        "__nova_mv_refresh_{}_{}",
        mv_definition.mv_id,
        uuid::Uuid::new_v4().simple()
    );
    let refresh_id = begin_staged_iceberg_mv_refresh_intent(
        state,
        target,
        mv_definition.mv_id,
        expected_main_snapshot_id,
        snapshots.clone(),
        &staging_branch,
    )?;
    let ident = iceberg_mv_table_ident(target)?;
    let refresh_marker = load_iceberg_mv_refresh_marker(state, refresh_id, mv_definition.mv_id)?;
    let marker = build_mv_refresh_provenance(
        &refresh_marker,
        RefreshTechnique::Incremental,
        build_mv_refresh_provenance_bases(
            &snapshots,
            &table_uuids,
            &mv_definition.last_refresh_snapshots,
        ),
        mv_definition_fingerprint(&mv_definition.select_sql),
        // TODO(W3a): thread exact row count. The incremental delta row counts
        // are only known after the change-stream write below, so the watermark
        // is stamped now and rows is left at 0.
        0,
    )
    .to_summary_properties()?;
    if let Err(err) = ensure_iceberg_mv_staging_branch(
        state,
        iceberg_catalog,
        target,
        &staging_branch,
        expected_main_snapshot_id,
        connector_context,
    ) {
        abort_iceberg_mv_refresh(state, refresh_id)?;
        return Err(err.into());
    }
    let target_table = match reload_iceberg_mv_target_table(target_entry, target) {
        Ok(table) => table,
        Err(err) => {
            return Err(handle_iceberg_mv_definite_pre_publish_error(
                state,
                target,
                target_entry,
                &staging_branch,
                refresh_id,
                err,
                connector_context,
            ));
        }
    };

    // 4. Build a one-shot `InMemoryCatalog` exposing the base table as a
    // *normal* Iceberg table (i.e. `ScanSource::IcebergDataFiles` whose
    // `IcebergTableInfo` carries the same catalog/namespace/table identity
    // as `ctx.rewrite.base_refs`). The IMV rewrite pipeline — invoked
    // inside `execute_query_with_options` when `mv_refresh_ctx` is `Some`
    // — wraps the root in `ImvDelta`, pushes the marker down to the leaf
    // scan, then `BindIcebergScanRule` rebinds the scan source to
    // `ScanSource::IcebergDeltaTable` using `find_base_ref` on the
    // `IcebergTableInfo` we publish here. `data_files = vec![]` is
    // intentional: the runtime `IcebergDeltaScan` operator obtains its
    // per-snapshot file list from the catalog at execution time.
    let refresh_base_refs = changes
        .iter()
        .map(|change| change.base_ref)
        .collect::<Vec<_>>();
    let catalog = match build_imv_refresh_catalog(state, &refresh_base_refs, &ctx.rewrite.pin) {
        Ok(c) => c,
        Err(err) => {
            return Err(handle_iceberg_mv_commit_error(
                state,
                target,
                target_entry,
                &staging_branch,
                refresh_id,
                err,
                connector_context,
            ));
        }
    };

    // 5. Parse the stored MV SELECT verbatim. No AST mutation: the IMV
    // rewrite pipeline owns delta/version binding and synthetic column
    // injection (`_row_id`, `__nova_action`, `__nova_base_row_id`,
    // `__change_op`).
    let normalized =
        match crate::sql::parser::dialect::normalize_for_raw_parse(&mv_definition.select_sql) {
            Ok(s) => s,
            Err(err) => {
                return Err(handle_iceberg_mv_commit_error(
                    state,
                    target,
                    target_entry,
                    &staging_branch,
                    refresh_id,
                    err,
                    connector_context,
                ));
            }
        };
    let statement = match crate::sql::parser::parse_normalized_sql_raw(&normalized) {
        Ok(s) => s,
        Err(err) => {
            return Err(handle_iceberg_mv_commit_error(
                state,
                target,
                target_entry,
                &staging_branch,
                refresh_id,
                format!("sql parser error: {err}"),
                connector_context,
            ));
        }
    };
    let sqlparser::ast::Statement::Query(query_box) = statement else {
        return Err(handle_iceberg_mv_commit_error(
            state,
            target,
            target_entry,
            &staging_branch,
            refresh_id,
            "REFRESH MATERIALIZED VIEW stored SQL must be a SELECT query".to_string(),
            connector_context,
        ));
    };
    let mut query = *query_box;
    if rewrite_evidence != RewriteMergeRefreshEvidence::None
        && rewrite_evidence != RewriteMergeRefreshEvidence::BranchUnionAggregate
    {
        alias_aggregate_refresh_group_key_projection(&mut query, ctx).map_err(|err| {
            handle_iceberg_mv_commit_error(
                state,
                target,
                target_entry,
                &staging_branch,
                refresh_id,
                err,
                connector_context,
            )
        })?;
    }
    // The analyzer view exposes <db>.<table>, not <cat>.<db>.<table>; strip
    // any catalog qualifier before binding.
    crate::sql::parser::query_refs::strip_catalog_from_three_part_names(&mut query);

    // 6. Use the RowDelta/DV commit path whenever the base change batch
    // carries DELETE-side rows or the IMV rewrite can emit change-stream
    // DELETE rows while applying existing target groups. Row location itself
    // must be carried by the plan as `_file` / `_pos`.
    let can_emit_delete_rows =
        has_delete_changes || apply_key.preload_locator_for_change_stream_deletes;

    // 7. Build the shared commit collector. The change-stream write DAG routes
    // writer reports back into this collector; the commit driver below consumes
    // the populated collector.
    let op_kind = if can_emit_delete_rows {
        CommitOpKind::RowDeltaDvFromFiles
    } else {
        CommitOpKind::FastAppend
    };
    let connectors_snapshot = state
        .connectors
        .read()
        .expect("standalone connector registry read lock")
        .clone();
    let aggregate_rewrite_validator;
    let imv_rewrite_validator: Option<&crate::engine::ImvRewriteValidator<'_>> = if rewrite_evidence
        != RewriteMergeRefreshEvidence::None
    {
        aggregate_rewrite_validator =
            |outcome: &crate::sql::planner::imv_rewrite::entrypoint::ImvRewriteOutcome| {
                validate_aggregate_refresh_rewrite_outcome(&ctx.rewrite, outcome, rewrite_evidence)
            };
        Some(&aggregate_rewrite_validator)
    } else {
        None
    };
    let planned_query = crate::engine::plan_query_for_iceberg_change_stream_refresh(
        &query,
        &catalog,
        &connectors_snapshot,
        current_database,
        Some(&ctx),
        imv_rewrite_validator,
        true,
    )
    .map_err(|err| {
        handle_iceberg_mv_commit_error(
            state,
            target,
            target_entry,
            &staging_branch,
            refresh_id,
            err,
            connector_context,
        )
    })?;
    let mut producer_branches = Vec::new();
    if can_emit_delete_rows {
        producer_branches.push(ImvChangeStreamProducerBranch::DeleteDv);
        producer_branches.push(ImvChangeStreamProducerBranch::ReuseData);
        producer_branches.push(ImvChangeStreamProducerBranch::FreshData);
    } else {
        producer_branches.push(ImvChangeStreamProducerBranch::FreshData);
    }
    let target_backend = iceberg_mv_target_backend(target);
    let populated = execute_imv_change_stream_write(
        state,
        &target_backend,
        target_table.clone(),
        &ident,
        op_kind,
        ImvRefreshPlannedChangeStream {
            optimized_tree: planned_query.optimized_tree,
            output_columns: planned_query.output_columns,
            change_stream: planned_query.change_stream,
            producer_branches,
            mv_refresh_ctx: Some(ctx),
        },
        &staging_branch,
    )
    .map_err(|err| {
        handle_iceberg_mv_commit_error(
            state,
            target,
            target_entry,
            &staging_branch,
            refresh_id,
            err.into_message(),
            connector_context,
        )
    })?;

    let (added_rows, deleted_rows) = match populated.effect {
        crate::mv::refresh::change_stream_write::ChangeStreamWriteEffect::Empty => (0, 0),
        crate::mv::refresh::change_stream_write::ChangeStreamWriteEffect::Changed {
            added_rows,
            deleted_rows,
        } => (added_rows, deleted_rows),
    };
    let collector = populated.collector;

    // 8b. Post-execution empty-delta short-circuit.
    //
    // The file-level `is_empty_delta` check earlier in this function only
    // catches snapshot ranges that produced no inserts and no deletes at all.
    // A snapshot range that inserted rows the MV's WHERE / PROJECT removes
    // (e.g. WHERE id > 10 with an inserted row of id=1) still appears
    // non-empty at the file level, so we enter the staging-branch path. Once
    // execution finishes the merge sink reports zero contributed rows; in
    // that case there is no Iceberg data to commit, and committing an empty
    // snapshot on the staging branch is both wasteful and confuses
    // downstream consumers that diff main vs the staging branch.
    //
    // Recovery: drop the staging branch (so the next refresh starts clean),
    // abort the staging-branch refresh intent, open a fresh metadata-only
    // refresh intent (no target / staging-branch fields), and finalize it
    // with the new base snapshot id. This mirrors the file-level empty-delta
    // short-circuit semantics: lineage advances without producing a new
    // Iceberg snapshot.
    if added_rows == 0 && deleted_rows == 0 {
        tracing::info!(
            snapshots = ?snapshots,
            "iceberg mv {}.{}.{}: incremental refresh produced 0 effective rows after SELECT \
             evaluation; advancing lineage without new iceberg snapshot",
            target.catalog,
            target.namespace,
            target.table
        );
        drop_iceberg_mv_staging_branch(
            state,
            target,
            target_entry,
            &staging_branch,
            connector_context,
        )?;
        abort_iceberg_mv_refresh(state, refresh_id)?;
        let metadata_refresh_id =
            begin_iceberg_mv_refresh_intent(state, mv_definition.mv_id, snapshots.clone())?;
        // W4/M6: the base watermark advanced but the MV output is net-zero, so
        // no data snapshot is committed above. Advance the lake watermark with a
        // data-free snapshot so the storage table's current-snapshot provenance
        // keeps up with the SQLite watermark; use its id as the recorded target
        // snapshot when committed.
        let target_snapshot_id = advance_lake_watermark_via_data_free_snapshot(
            target,
            target_entry,
            iceberg_catalog,
            mv_definition,
            metadata_refresh_id,
            &snapshots,
            &table_uuids,
        )?
        .map(Ok)
        .unwrap_or_else(|| recorded_target_snapshot_id(target, mv_definition))?;
        finalize_iceberg_mv_refresh_with_partition_state(
            state,
            metadata_refresh_id,
            mv_definition.last_refresh_rows.unwrap_or(0),
            snapshots,
            table_uuids,
            target_snapshot_id,
            IcebergMvPartitionStateFinalize::FromAffected(&ctx.affected_partitions),
        )
        .map_err(iceberg_mv_post_publish_finalize_error)?;
        return Ok(StatementResult::Ok);
    }

    // 9. Drive the commit from the populated collector.
    let new_snapshot_id = match data_block_on(commit_iceberg_mv_with_populated_collector(
        &target_table,
        iceberg_catalog,
        target_entry,
        &ident,
        Arc::clone(&collector),
        &staging_branch,
        marker,
    )) {
        Ok(Ok(outcome)) => outcome.new_snapshot_id,
        Ok(Err(err)) => {
            return Err(handle_iceberg_mv_commit_service_error(
                state,
                target,
                target_entry,
                &staging_branch,
                refresh_id,
                err,
                connector_context,
            ));
        }
        Err(err) => {
            return Err(handle_iceberg_mv_definite_pre_publish_error(
                state,
                target,
                target_entry,
                &staging_branch,
                refresh_id,
                err,
                connector_context,
            ));
        }
    };

    let new_total_rows = mv_definition
        .last_refresh_rows
        .unwrap_or(0)
        .checked_add(added_rows)
        .and_then(|rows| rows.checked_sub(deleted_rows))
        .ok_or_else(|| {
            format!(
                "iceberg MV row-count delta overflow: current={:?}, inserts={added_rows}, deletes={deleted_rows}",
                mv_definition.last_refresh_rows
            )
        })?;
    record_iceberg_mv_staging_commit(
        state,
        refresh_id,
        new_snapshot_id,
        new_total_rows,
        table_uuids.clone(),
    )?;
    let published_snapshot_id = resolve_iceberg_mv_publication(
        state,
        target,
        target_entry,
        &staging_branch,
        refresh_id,
        None,
        connector_context,
        publish_iceberg_mv_refresh(
            state,
            target,
            target_entry,
            &staging_branch,
            expected_main_snapshot_id,
            new_snapshot_id,
            refresh_id,
            mv_definition.mv_id,
            connector_context,
        ),
    )?;
    record_iceberg_mv_publish_commit(state, refresh_id, published_snapshot_id)?;
    drop_iceberg_mv_staging_branch(
        state,
        target,
        target_entry,
        &staging_branch,
        connector_context,
    )?;
    finalize_iceberg_mv_refresh_with_partition_state(
        state,
        refresh_id,
        new_total_rows,
        snapshots.clone(),
        table_uuids.clone(),
        published_snapshot_id,
        IcebergMvPartitionStateFinalize::FromAffected(&ctx.affected_partitions),
    )
    .map_err(iceberg_mv_post_publish_finalize_error)?;

    tracing::info!(
        "iceberg mv {}.{}.{}: incremental refresh complete: \
         added_rows={added_rows} deleted_rows={deleted_rows} total_rows={new_total_rows} iceberg_snapshot={published_snapshot_id}",
        target.catalog,
        target.namespace,
        target.table
    );
    Ok(StatementResult::Ok)
}

/// Write `chunks` into the given iceberg table as Parquet data files.
///
/// Returns the list of written `DataFile` descriptors. If `chunks` is empty
/// or all chunks contain zero rows, returns an empty vec.
///
/// The RecordBatches are re-cast to an Arrow schema annotated with the
/// Iceberg field ids that the `ParquetWriterBuilder` requires (it matches
/// columns by field-id metadata by default).
pub(crate) async fn write_chunks_as_iceberg_data_files(
    table: &iceberg::table::Table,
    chunks: &[crate::exec::chunk::Chunk],
) -> Result<Vec<iceberg::spec::DataFile>, String> {
    write_record_batches_as_data_files(table, chunks.iter().map(|chunk| chunk.batch.clone())).await
}

#[cfg(test)]
pub(crate) fn drop_iceberg_mv(
    state: &Arc<StandaloneState>,
    current_catalog: Option<&str>,
    current_database: &str,
    stmt: &DropMaterializedViewStmt,
) -> Result<StatementResult, String> {
    drop_iceberg_mv_with_connector_context(
        state,
        current_catalog,
        current_database,
        stmt,
        &crate::connector::test_request_context(),
    )
}

pub(crate) fn drop_iceberg_mv_with_connector_context(
    state: &Arc<StandaloneState>,
    current_catalog: Option<&str>,
    current_database: &str,
    stmt: &DropMaterializedViewStmt,
    connector_context: &novarocks_spi::connector::ConnectorRequestContext,
) -> Result<StatementResult, String> {
    crate::connector::validate_request_context(connector_context)?;
    let _refresh_guard = acquire_mv_refresh_lock()?;
    let target = resolve_drop_target(current_catalog, current_database, &stmt.name)?;
    if !preflight_iceberg_mv_drop(state, &target, stmt.if_exists)? {
        return Ok(StatementResult::Ok);
    }

    let instance_id = novarocks_spi::connector::ConnectorInstanceId::parse(&target.catalog)
        .map_err(|error| error.to_string())?;
    crate::connector::mutation::execute_catalog_mutation(
        state.connector_control.as_ref(),
        &instance_id,
        novarocks_spi::connector::ConnectorCatalogMutationOperation::DropTable {
            table: novarocks_spi::connector::ConnectorTableIdentity {
                instance_id: instance_id.clone(),
                namespace: Arc::from(target.namespace.as_str()),
                table: Arc::from(target.table.as_str()),
            },
            policy: novarocks_spi::connector::DropPolicy::FailIfMissing,
            data_disposition: novarocks_spi::connector::ConnectorDropTableDataDisposition::Purge,
        },
        connector_context.clone(),
    )?;
    drop_iceberg_mv_metadata(state, &target)?;
    crate::engine::query_prep::drop_local_table_registration_if_exists(
        state,
        &target.namespace,
        &target.table,
    )?;

    tracing::info!(
        "iceberg mv {}.{}.{}: dropped successfully",
        target.catalog,
        target.namespace,
        target.table
    );
    Ok(StatementResult::Ok)
}

fn drop_iceberg_mv_metadata(
    state: &Arc<StandaloneState>,
    target: &IcebergMvTarget,
) -> Result<(), String> {
    let dropped = state
        .mv_repository
        .drop_by_target(&crate::mv::model::MvTarget {
            catalog: Some(target.catalog.clone()),
            database: target.namespace.clone(),
            name: target.table.clone(),
        })
        .map_err(|e| format!("drop iceberg mv metadata failed: {e}"))?;
    if !dropped {
        return Err(format!(
            "materialized view {}.{}.{} metadata disappeared during drop",
            target.catalog, target.namespace, target.table
        ));
    }
    Ok(())
}

fn preflight_iceberg_mv_drop(
    state: &Arc<StandaloneState>,
    target: &IcebergMvTarget,
    if_exists: bool,
) -> Result<bool, String> {
    let Some(definition) = state
        .mv_repository
        .find_by_target(&crate::mv::model::MvTarget {
            catalog: Some(target.catalog.clone()),
            database: target.namespace.clone(),
            name: target.table.clone(),
        })
        .map_err(|e| format!("load iceberg mv definition for drop failed: {e}"))?
    else {
        if if_exists {
            return Ok(false);
        }
        return Err(format!(
            "materialized view does not exist: {}.{}.{}",
            target.catalog, target.namespace, target.table
        ));
    };
    if definition.refresh_in_progress || definition.active_refresh_id.is_some() {
        return Err(format!(
            "cannot drop materialized view {}.{}.{}: refresh in progress",
            target.catalog, target.namespace, target.table
        ));
    }
    crate::engine::mv::dependency::ensure_no_downstream_dependencies(
        state,
        &crate::mv::dependency::model::iceberg_mv_dependency_ref(
            &target.catalog,
            &target.namespace,
            &target.table,
        ),
    )?;
    Ok(true)
}

fn resolve_drop_target(
    current_catalog: Option<&str>,
    current_database: &str,
    name: &ObjectName,
) -> Result<IcebergMvTarget, String> {
    let catalog = current_catalog.ok_or_else(|| {
        "DROP MATERIALIZED VIEW for an Iceberg MV requires current Iceberg catalog context"
            .to_string()
    })?;
    let (namespace, table) = resolve_mv_name(name, current_database)?;
    Ok(IcebergMvTarget {
        catalog: novarocks_catalog::identifier::normalize_identifier(catalog)?,
        namespace,
        table,
    })
}

/// Build an Iceberg `Schema` from the MV's analyzed output columns.
/// Each column is mapped to a primitive Iceberg type; nullable columns become
/// optional fields, non-nullable columns become required fields.
#[cfg(test)]
fn build_iceberg_schema_from_outputs(output_columns: &[OutputColumn]) -> Result<Schema, String> {
    let mut fields = Vec::with_capacity(output_columns.len());
    for (idx, col) in output_columns.iter().enumerate() {
        let id = (idx + 1) as i32;
        let primitive = arrow_data_type_to_iceberg_primitive(&col.data_type)?;
        let field: Arc<NestedField> = if col.nullable {
            NestedField::optional(id, &col.name, Type::Primitive(primitive)).into()
        } else {
            NestedField::required(id, &col.name, Type::Primitive(primitive)).into()
        };
        fields.push(field);
    }
    Schema::builder()
        .with_fields(fields)
        .build()
        .map_err(|e| format!("build iceberg mv schema failed: {e}"))
}

/// Map an Arrow `DataType` to an Iceberg `PrimitiveType`. Returns an error
/// for types that cannot be represented as Iceberg primitive columns.
#[cfg(test)]
fn arrow_data_type_to_iceberg_primitive(
    arrow_type: &arrow::datatypes::DataType,
) -> Result<PrimitiveType, String> {
    use arrow::datatypes::{DataType, TimeUnit};
    Ok(match arrow_type {
        DataType::Boolean => PrimitiveType::Boolean,
        // Promote narrow integer types — Iceberg has no Int8/Int16 primitive.
        DataType::Int8 | DataType::Int16 => PrimitiveType::Int,
        DataType::Int32 => PrimitiveType::Int,
        DataType::Int64 => PrimitiveType::Long,
        DataType::Float32 => PrimitiveType::Float,
        DataType::Float64 => PrimitiveType::Double,
        DataType::Date32 => PrimitiveType::Date,
        DataType::Timestamp(TimeUnit::Microsecond, _) => PrimitiveType::Timestamp,
        DataType::Utf8 | DataType::LargeUtf8 => PrimitiveType::String,
        DataType::Binary | DataType::LargeBinary => PrimitiveType::Binary,
        DataType::Decimal128(precision, scale) => {
            let scale_u32 = u32::try_from(*scale).map_err(|_| {
                format!("iceberg-backed mv: Decimal128 negative scale {scale} is not supported")
            })?;
            PrimitiveType::Decimal {
                precision: *precision as u32,
                scale: scale_u32,
            }
        }
        DataType::Decimal256(_, _) => {
            return Err(
                "iceberg-backed mv: Decimal256 (precision > 38) is not supported by Iceberg; \
                 use DECIMAL with precision <= 38"
                    .to_string(),
            );
        }
        DataType::FixedSizeBinary(16) => {
            return Err(
                "iceberg-backed mv: LARGEINT (FixedSizeBinary(16)) is not supported in \
                 iceberg-backed MV; use BIGINT or DECIMAL"
                    .to_string(),
            );
        }
        other => {
            return Err(format!(
                "iceberg-backed mv: unsupported column type `{other:?}`"
            ));
        }
    })
}

