    fn string_i64_i64_rows(
        result: &crate::runtime::query_result::QueryResult,
    ) -> Vec<(String, i64, i64)> {
        let mut rows = Vec::new();
        for chunk in &result.chunks {
            let category = chunk
                .batch
                .column(0)
                .as_any()
                .downcast_ref::<StringArray>()
                .expect("category column");
            let count = chunk
                .batch
                .column(1)
                .as_any()
                .downcast_ref::<Int64Array>()
                .expect("count column");
            let sum = chunk
                .batch
                .column(2)
                .as_any()
                .downcast_ref::<Int64Array>()
                .expect("sum column");
            for row in 0..chunk.batch.num_rows() {
                rows.push((
                    category.value(row).to_string(),
                    count.value(row),
                    sum.value(row),
                ));
            }
        }
        rows
    }

    fn id_name_rows(result: &crate::runtime::query_result::QueryResult) -> Vec<(i32, String)> {
        let mut rows = Vec::new();
        for chunk in &result.chunks {
            let id = chunk
                .batch
                .column(0)
                .as_any()
                .downcast_ref::<Int32Array>()
                .expect("id column");
            let name = chunk
                .batch
                .column(1)
                .as_any()
                .downcast_ref::<StringArray>()
                .expect("name column");
            for row in 0..chunk.batch.num_rows() {
                rows.push((id.value(row), name.value(row).to_string()));
            }
        }
        rows
    }

