    fn single_int_chunk(values: &[i32]) -> Vec<crate::exec::chunk::Chunk> {
        let arrow_schema = StdArc::new(ArrowSchema::new(vec![Field::new(
            "k",
            DataType::Int32,
            false,
        )]));
        let batch = RecordBatch::try_new(
            arrow_schema.clone(),
            vec![StdArc::new(Int32Array::from(values.to_vec()))],
        )
        .expect("record batch");
        let chunk_schema_ref = crate::exec::chunk::ChunkSchema::try_ref_from_schema_and_slot_ids(
            &arrow_schema,
            &[crate::common::ids::SlotId(0)],
        )
        .expect("chunk schema");
        vec![crate::exec::chunk::Chunk::new_with_chunk_schema(
            batch,
            chunk_schema_ref,
        )]
    }

    fn id_name_chunk(rows: &[(i32, &str)]) -> Vec<crate::exec::chunk::Chunk> {
        let arrow_schema = StdArc::new(ArrowSchema::new(vec![
            Field::new("id", DataType::Int32, false),
            Field::new("name", DataType::Utf8, true),
            Field::new(HIDDEN_APPLY_KEY_COLUMN_NAME, DataType::Int64, false),
        ]));
        let batch = RecordBatch::try_new(
            arrow_schema.clone(),
            vec![
                StdArc::new(Int32Array::from_iter_values(rows.iter().map(|(id, _)| *id))),
                StdArc::new(StringArray::from_iter_values(
                    rows.iter().map(|(_, name)| *name),
                )),
                StdArc::new(Int64Array::from_iter_values(
                    rows.iter()
                        .enumerate()
                        .map(|(idx, _)| 1_000_i64 + idx as i64),
                )),
            ],
        )
        .expect("record batch");
        let chunk_schema_ref = crate::exec::chunk::ChunkSchema::try_ref_from_schema_and_slot_ids(
            &arrow_schema,
            &[
                crate::common::ids::SlotId(0),
                crate::common::ids::SlotId(1),
                crate::common::ids::SlotId(2),
            ],
        )
        .expect("chunk schema");
        vec![crate::exec::chunk::Chunk::new_with_chunk_schema(
            batch,
            chunk_schema_ref,
        )]
    }

    fn seed_active_staging_refresh(
        state: &Arc<StandaloneState>,
        catalog_name: &str,
        namespace: &str,
        table_name: &str,
        publish_main: bool,
    ) -> i64 {
        let mv = find_iceberg_mv_definition(state, catalog_name, namespace, table_name)
            .expect("mv definition");
        let target = IcebergMvTarget {
            catalog: catalog_name.to_string(),
            namespace: namespace.to_string(),
            table: table_name.to_string(),
        };
        let entry = {
            let catalogs = state.iceberg_catalogs.read().expect("iceberg catalogs");
            catalogs.get(catalog_name).expect("catalog")
        };
        let iceberg_catalog =
            crate::connector::iceberg::catalog::registry::build_iceberg_catalog(&entry)
                .expect("catalog");
        let loaded = crate::connector::iceberg::catalog::load_table(&entry, namespace, table_name)
            .expect("load target table");
        let expected_main_snapshot_id = loaded
            .table
            .metadata()
            .current_snapshot()
            .map(|snapshot| snapshot.snapshot_id());
        let staging_branch = format!("__nova_mv_refresh_test_{}", uuid::Uuid::new_v4().simple());
        let connector_context = crate::connector::test_request_context();
        ensure_iceberg_mv_staging_branch(
            state,
            &iceberg_catalog,
            &target,
            &staging_branch,
            expected_main_snapshot_id,
            &connector_context,
        )
        .expect("create staging branch");
        let refresh_id = begin_staged_iceberg_mv_refresh_intent(
            state,
            &target,
            mv.mv_id,
            expected_main_snapshot_id,
            BTreeMap::new(),
            &staging_branch,
        )
        .expect("begin staged refresh");
        let marker = load_iceberg_mv_refresh_marker(state, refresh_id, mv.mv_id)
            .expect("marker")
            .to_summary_properties();

        let staging_snapshot = data_block_on(async {
            let ident = iceberg_mv_table_ident(&target).expect("ident");
            let table = iceberg_catalog
                .load_table(&ident)
                .await
                .expect("load target");
            let chunks = id_name_chunk(&[(1, "staged")]);
            let written = write_chunks_as_iceberg_data_files(&table, &chunks)
                .await
                .expect("write chunks");
            commit_iceberg_mv_target_files_with_ref(
                &table,
                &iceberg_catalog,
                &entry,
                &ident,
                CommitOpKind::FastAppend,
                written,
                &staging_branch,
                marker,
            )
            .await
            .expect("commit staging")
            .new_snapshot_id
        })
        .expect("runtime");
        record_iceberg_mv_staging_commit(state, refresh_id, staging_snapshot, 1, BTreeMap::new())
            .expect("record staging");

        if publish_main {
            let published_snapshot = publish_iceberg_mv_refresh(
                state,
                &target,
                &entry,
                &staging_branch,
                expected_main_snapshot_id,
                staging_snapshot,
                refresh_id,
                mv.mv_id,
                &crate::connector::test_request_context(),
            )
            .expect("publish staging");
            record_iceberg_mv_publish_commit(state, refresh_id, published_snapshot)
                .expect("record publish");
            published_snapshot
        } else {
            staging_snapshot
        }
    }

    fn advance_target_main_without_refresh_marker(
        state: &Arc<StandaloneState>,
        catalog_name: &str,
        namespace: &str,
        table_name: &str,
    ) -> i64 {
        let entry = {
            let catalogs = state.iceberg_catalogs.read().expect("iceberg catalogs");
            catalogs.get(catalog_name).expect("catalog")
        };
        let iceberg_catalog =
            crate::connector::iceberg::catalog::registry::build_iceberg_catalog(&entry)
                .expect("catalog");
        let target = IcebergMvTarget {
            catalog: catalog_name.to_string(),
            namespace: namespace.to_string(),
            table: table_name.to_string(),
        };
        data_block_on(async {
            let ident = iceberg_mv_table_ident(&target).expect("ident");
            let table = iceberg_catalog
                .load_table(&ident)
                .await
                .expect("load target");
            let chunks = id_name_chunk(&[(99, "external")]);
            let written = write_chunks_as_iceberg_data_files(&table, &chunks)
                .await
                .expect("write chunks");
            commit_iceberg_mv_target_files_with_ref(
                &table,
                &iceberg_catalog,
                &entry,
                &ident,
                CommitOpKind::FastAppend,
                written,
                "main",
                BTreeMap::new(),
            )
            .await
            .expect("commit external main")
            .new_snapshot_id
        })
        .expect("runtime")
    }

    #[test]
    fn create_iceberg_mv_creates_branch_capable_v3_target() {
        let env = open_test_state_with_iceberg_catalog("ice", "analytics");
        create_base_table(&env.state, "ice", "sales", "orders");
        let stmt = parse_create_mv(
            "CREATE MATERIALIZED VIEW mv_orders
             DISTRIBUTED BY HASH(id) BUCKETS 1
             PROPERTIES('storage_engine'='iceberg')
             AS SELECT id, name FROM ice.sales.orders",
        );

        create_iceberg_mv(&env.state, Some("ice"), &env.current_db, &stmt)
            .expect("create iceberg mv");

        let entry = {
            let catalogs = env.state.iceberg_catalogs.read().expect("iceberg catalogs");
            catalogs.get("ice").expect("catalog")
        };
        let loaded =
            crate::connector::iceberg::catalog::load_table(&entry, "analytics", "mv_orders")
                .expect("load target table");
        assert_eq!(
            loaded.table.metadata().format_version(),
            iceberg::spec::FormatVersion::V3
        );
        assert_eq!(
            loaded
                .table
                .metadata()
                .properties()
                .get("write.row-lineage")
                .map(String::as_str),
            Some("true")
        );
        assert_eq!(
            loaded
                .table
                .metadata()
                .properties()
                .get(APPLY_KEY_COLUMN_PROPERTY)
                .map(String::as_str),
            Some(HIDDEN_APPLY_KEY_COLUMN_NAME)
        );
        let fields = loaded
            .table
            .metadata()
            .current_schema()
            .as_struct()
            .fields();
        let apply_key_field = fields
            .iter()
            .find(|field| field.name == HIDDEN_APPLY_KEY_COLUMN_NAME)
            .expect("target apply-key field");
        assert_eq!(apply_key_field.id, 3);
        assert!(apply_key_field.required);
        assert_eq!(
            find_iceberg_mv_definition(&env.state, "ice", "analytics", "mv_orders")
                .expect("mv definition")
                .schema_contract
                .expect("schema contract")
                .target
                .hidden_apply_key
                .target_field_id,
            3
        );
    }

    #[test]
    fn create_iceberg_mv_writes_descriptor_property_on_mv_table() {
        let env = open_test_state_with_iceberg_catalog("ice", "analytics");
        create_base_table(&env.state, "ice", "sales", "orders");
        let stmt = parse_create_mv(
            "CREATE MATERIALIZED VIEW mv_orders
             DISTRIBUTED BY HASH(id) BUCKETS 1
             PROPERTIES('storage_engine'='iceberg')
             AS SELECT id, name FROM ice.sales.orders",
        );

        create_iceberg_mv(&env.state, Some("ice"), &env.current_db, &stmt)
            .expect("create iceberg mv");

        let entry = {
            let catalogs = env.state.iceberg_catalogs.read().expect("iceberg catalogs");
            catalogs.get("ice").expect("catalog")
        };
        let loaded =
            crate::connector::iceberg::catalog::load_table(&entry, "analytics", "mv_orders")
                .expect("load MV table");
        let descriptor =
            MvDescriptorV1::from_storage_properties(loaded.table.metadata().properties())
                .expect("descriptor properties");

        assert_eq!(descriptor.descriptor_version, MV_DESCRIPTOR_VERSION);
        assert_eq!(descriptor.package_id, "analytics.mv_orders");
        assert_eq!(
            descriptor.logical_sql,
            "SELECT id, name FROM ice.sales.orders"
        );
        assert_eq!(descriptor.dialect, "starrocks");
        assert_eq!(
            descriptor.visible_columns,
            vec!["id".to_string(), "name".to_string()]
        );
        assert_eq!(
            descriptor.hidden_columns,
            vec![HIDDEN_APPLY_KEY_COLUMN_NAME.to_string()]
        );
        assert_eq!(
            descriptor.base_dependencies,
            vec![DescriptorDependency {
                catalog: "ice".to_string(),
                namespace: "sales".to_string(),
                name: "orders".to_string(),
                object_type: "table".to_string(),
                storage_engine: "iceberg".to_string(),
            }]
        );
        // W2: CREATE now pushes the freshly-persisted schema contract into the
        // MV table descriptor after the metadata transaction commits (see
        // sync_iceberg_mv_descriptor_for_target). Previously this field stayed
        // `None` on the descriptor written at create_table time, because the
        // contract needs the created target table's field-ids.
        let target = IcebergMvTarget {
            catalog: "ice".to_string(),
            namespace: "analytics".to_string(),
            table: "mv_orders".to_string(),
        };
        let stored_definition = load_iceberg_mv_definition_by_target(&env.state, &target)
            .expect("load stored mv definition");
        assert_eq!(
            descriptor.schema_contract_typed().expect("typed contract"),
            stored_definition.schema_contract
        );
        assert!(descriptor.schema_contract_typed().unwrap().is_some());
        assert_eq!(
            descriptor.refresh_contract,
            Some(serde_json::json!({
                "policy": "DEFERRED_MANUAL",
                "interval_ms": null,
                "paused": false,
            }))
        );
        assert!(descriptor.created_at_ms > 0);

        let legacy_alias_name = ["__nr", "_mv_", "mv_orders"].concat();
        let missing_direct_target_err =
            crate::connector::iceberg::catalog::load_table(&entry, "analytics", &legacy_alias_name)
                .expect_err("legacy alias target table must not exist");
        assert!(
            missing_direct_target_err.contains(&legacy_alias_name),
            "{missing_direct_target_err}"
        );
    }

    #[test]
    fn iceberg_mv_reader_loads_target_table_without_alias() {
        let env = open_test_state_with_iceberg_catalog("ice", "analytics");
        create_base_table(&env.state, "ice", "sales", "orders");
        let stmt = parse_create_mv(
            "CREATE MATERIALIZED VIEW mv_orders
             DISTRIBUTED BY HASH(id) BUCKETS 1
             PROPERTIES('storage_engine'='iceberg')
             AS SELECT id, name FROM ice.sales.orders",
        );
        create_iceberg_mv(&env.state, Some("ice"), &env.current_db, &stmt)
            .expect("create iceberg mv");

        let resolved = crate::connector::metadata_load_table(
            env.state.connector_control.as_ref(),
            crate::connector::test_request_context(),
            "ice",
            "analytics",
            "mv_orders",
            novarocks_spi::connector::ConnectorTableResolution::StrictBaseTable,
        )
        .expect("read MV table by public name")
        .0;
        assert_eq!(resolved.table, "mv_orders");

        let (schema_table, schema_id) = crate::connector::metadata_load_table(
            env.state.connector_control.as_ref(),
            crate::connector::test_request_context(),
            "ice",
            "analytics",
            "mv_orders",
            novarocks_spi::connector::ConnectorTableResolution::StrictBaseTable,
        )
        .expect("read MV schema id by public name");
        assert_eq!(schema_table.table, "mv_orders");
        assert!(schema_id.is_some());

        let legacy_alias_name = ["__nr", "_mv_", "mv_orders"].concat();
        let missing_schema_err = crate::connector::metadata_load_table(
            env.state.connector_control.as_ref(),
            crate::connector::test_request_context(),
            "ice",
            "analytics",
            &legacy_alias_name,
            novarocks_spi::connector::ConnectorTableResolution::StrictBaseTable,
        )
        .expect_err("legacy alias schema id must not resolve");
        assert!(
            missing_schema_err.contains(&legacy_alias_name) || missing_schema_err.contains("not"),
            "{missing_schema_err}"
        );

        let missing_target_err = crate::connector::metadata_load_table(
            env.state.connector_control.as_ref(),
            crate::connector::test_request_context(),
            "ice",
            "analytics",
            &legacy_alias_name,
            novarocks_spi::connector::ConnectorTableResolution::StrictBaseTable,
        )
        .expect_err("legacy alias target must not resolve");
        assert!(
            missing_target_err.contains(&legacy_alias_name) || missing_target_err.contains("not"),
            "{missing_target_err}"
        );
    }

